import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo8: HistoricalDocument = {
  id: 'codigo-manu-capitulo-8',
  title: 'Capítulo VIII',
  subtitle: 'Dos Processos Civis e Criminais',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Regula os dezoito títulos de litígio, os processos judiciais, as penas e o direito penal.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo VIII',
      type: 'articles',
      articles: [
        { id: 'cm-8-1', number: 'Verso 1', text: `Um rei, desejoso de investigar casos legais, deve entrar em seu tribunal de justiça, preservando um comportamento digno, junto com *Brahmanas* e com conselheiros experientes.` },
        { id: 'cm-8-2', number: 'Verso 2', text: `Ali, quer sentado quer de pé, erguendo o seu braço direito, sem ostentação em suas vestes e ornamentos, que ele examine os negócios dos litigantes,` },
        { id: 'cm-8-3', number: 'Verso 3', text: `Diariamente (decidindo) um após o outro (todos os casos) que se enquadram sob os dezoito títulos (da lei) de acordo com princípios extraídos dos costumes locais e dos Institutos da lei sagrada.` },
        { id: 'cm-8-4', number: 'Verso 4', text: `Desses (títulos) o primeiro é o não pagamento de dívidas, (depois seguem), (2) depósito e penhor, (3) venda sem propriedade, (4) questões entre sócios, e (5) retomada de doações,` },
        { id: 'cm-8-5', number: 'Verso 5', text: `(6) Não pagamento de salários, (7) não cumprimento de acordos, (8) rescisão de venda e compra, (9) disputas entre o dono (de gado) e seus servos,` },
        { id: 'cm-8-6', number: 'Verso 6', text: `(10) Disputas a respeito de limites, (11) agressão e (12) difamação, (13) roubo, (14) assalto e violência, (15) adultério,` },
        { id: 'cm-8-7', number: 'Verso 7', text: `(16) Deveres do marido e da esposa, (17) partilha (de herança), (18) jogos de azar e apostas; estes são neste mundo os dezoito tópicos que dão origem a processos judiciais.` },
        { id: 'cm-8-8', number: 'Verso 8', text: `Dependendo da lei eterna, que ele decida os processos dos homens que em sua maioria contendem sobre os títulos recém-mencionados.` },
        { id: 'cm-8-9', number: 'Verso 9', text: `Mas se o rei não investiga pessoalmente os processos, então que ele nomeie um *Brahmana* erudito para julgá-los.` },
        { id: 'cm-8-10', number: 'Verso 10', text: `Esse (homem) deverá entrar naquele tribunal mui excelente, acompanhado por três assessores, e considerar plenamente (todas) as causas (trazidas) perante o (rei), quer sentando-se quer de pé.` },
        { id: 'cm-8-11', number: 'Verso 11', text: `Onde três *Brahmanas* versados nos Vedas e o erudito (juiz) nomeado pelo rei se sentam, eles chamam isso de tribunal do *Brahman* (de quatro rostos).` },
        { id: 'cm-8-12', number: 'Verso 12', text: `Mas onde a justiça, ferida pela injustiça, se aproxima e os juízes não extraem o dardo, ali (eles também) são feridos (por esse dardo da injustiça).` },
        { id: 'cm-8-13', number: 'Verso 13', text: `Ou não se deve entrar no tribunal, ou a verdade deve ser dita; um homem que nada diz ou fala falsamente, torna-se pecaminoso.` },
        { id: 'cm-8-14', number: 'Verso 14', text: `Onde a justiça é destruída pela injustiça, ou a verdade pela falsidade, enquanto os juízes observam, ali eles também serão destruídos.` },
        { id: 'cm-8-15', number: 'Verso 15', text: `'A justiça, sendo violada, destrói; a justiça, sendo preservada, preserva: portanto a justiça não deve ser violada, para que a justiça violada não nos destrua.'` },
        { id: 'cm-8-16', number: 'Verso 16', text: `Pois a justiça divina (é dita ser) um touro (*vrisha*); aquele (homem) que a viola (*kurute 'lam*) os deuses consideram ser (um homem desprezível como) um *Sudra* (*vrishala*); que ele, portanto, cuide para não violar a justiça.` },
        { id: 'cm-8-17', number: 'Verso 17', text: `O único amigo que segue os homens mesmo após a morte é a justiça; pois tudo o mais é perdido ao mesmo tempo em que o corpo (perece).` },
        { id: 'cm-8-18', number: 'Verso 18', text: `Um quarto da (culpa de uma) (decisão) injusta recai sobre aquele que cometeu (o crime), um quarto sobre a testemunha (falsa), um quarto sobre todos os juízes, um quarto sobre o rei.` },
        { id: 'cm-8-19', number: 'Verso 19', text: `Mas onde aquele que é digno de condenação é condenado, o rei está livre de culpa, e os juízes são salvos (do pecado); a culpa recai sobre o perpetrador (do crime apenas).` },
        { id: 'cm-8-20', number: 'Verso 20', text: `Um *Brahmana* que subsiste apenas pelo nome de sua casta (*gati*), ou um que meramente se chama de *Brahmana* (embora sua origem seja incerta), pode, a bel-prazer do rei, interpretar a lei para ele, mas nunca um *Sudra*.` },
        { id: 'cm-8-21', number: 'Verso 21', text: `O reino daquele monarca, que observa enquanto um *Sudra* resolve a lei, afundará (baixo), como uma vaca em um pântano.` },
        { id: 'cm-8-22', number: 'Verso 22', text: `Aquele reino onde os *Sudras* são muito numerosos, o qual é infestado por ateus e destituído de (habitantes) duas vezes nascidos, logo perece inteiramente, afligido pela fome e pela doença.` },
        { id: 'cm-8-23', number: 'Verso 23', text: `Tendo ocupado o assento da justiça, tendo coberto o seu corpo, e tendo adorado as deidades guardiãs do mundo, que ele, com a mente concentrada, inicie o julgamento das causas.` },
        { id: 'cm-8-24', number: 'Verso 24', text: `Conhecendo o que é conveniente ou inconveniente, o que é pura justiça ou injustiça, que ele examine as causas dos litigantes de acordo com a ordem das castas (*varna*).` },
        { id: 'cm-8-25', number: 'Verso 25', text: `Por sinais externos que ele descubra a disposição interna dos homens, por sua voz, sua cor, seus movimentos, seu aspecto, seus olhos e seus gestos.` },
        { id: 'cm-8-26', number: 'Verso 26', text: `O (funcionamento) interno da mente é percebido através do aspecto, dos movimentos, da marcha, dos gestos, da fala, e das mudanças no olho e da face.` },
        { id: 'cm-8-27', number: 'Verso 27', text: `O rei deve proteger a propriedade herdada (e outras) de um menor, até que ele tenha retornado (da casa do seu professor) ou até que ele tenha passado da sua minoridade.` },
        { id: 'cm-8-28', number: 'Verso 28', text: `De maneira semelhante, deve-se tomar cuidado das mulheres estéreis, daquelas que não têm filhos, daquelas cuja família está extinta, das esposas e viúvas fiéis aos seus senhores, e das mulheres afligidas por doenças.` },
        { id: 'cm-8-29', number: 'Verso 29', text: `Um rei justo deve punir como ladrões aqueles parentes que se apropriam da propriedade de tais fêmeas durante a vida delas.` },
        { id: 'cm-8-30', number: 'Verso 30', text: `A propriedade, cujo dono desapareceu, o rei fará com que seja mantida como um depósito durante três anos; dentro do período de três anos o dono pode reivindicá-la, após (esse prazo) o rei pode tomá-la.` },
        { id: 'cm-8-31', number: 'Verso 31', text: `Aquele que diz, 'Isto me pertence', deve ser examinado de acordo com a regra; se ele descrever com precisão a forma, e o número (dos artigos encontrados) e assim por diante, (ele é) o proprietário, (e) deve (receber) essa propriedade.` },
        { id: 'cm-8-32', number: 'Verso 32', text: `Mas se ele realmente não sabe o tempo e o lugar (onde foi) perdida, sua cor, forma e tamanho, ele é digno de uma multa igual (em valor) ao (objeto reivindicado).` },
        { id: 'cm-8-33', number: 'Verso 33', text: `Agora o rei, lembrando-se do dever dos homens bons, pode tomar a sexta parte da propriedade perdida e depois encontrada, ou um décimo, ou pelo menos um doze avos.` },
        { id: 'cm-8-34', number: 'Verso 34', text: `A propriedade perdida e depois encontrada (pelos servos do rei) deverá permanecer sob a guarda de funcionários (especiais); aqueles que o rei condenar por roubá-la, ele fará com que sejam mortos por um elefante.` },
        { id: 'cm-8-35', number: 'Verso 35', text: `Daquele homem que disser verdadeiramente a respeito de tesouros achados, 'Isto me pertence', o rei pode tomar um sexto ou um doze avos.` },
        { id: 'cm-8-36', number: 'Verso 36', text: `Mas aquele que disser falsamente (isso), será multado em um oitavo de sua propriedade, ou, tendo sido feito um cálculo do (valor do) tesouro, em alguma porção menor (disso).` },
        { id: 'cm-8-37', number: 'Verso 37', text: `Quando um *Brahmana* erudito encontrou um tesouro, depositado em (tempos) anteriores, ele pode tomar até mesmo o todo (dele); pois ele é o mestre de tudo.` },
        { id: 'cm-8-38', number: 'Verso 38', text: `Quando o rei encontra um tesouro de antigamente escondido na terra, que ele dê metade aos *Brahmanas* e coloque a (outra) metade em seu tesouro.` },
        { id: 'cm-8-39', number: 'Verso 39', text: `O rei obtém metade dos tesouros antigos e metais (encontrados) na terra, em razão de (ele dar) proteção, (e) porque ele é o senhor do solo.` },
        { id: 'cm-8-40', number: 'Verso 40', text: `A propriedade roubada por ladrões deve ser restaurada pelo rei a (homens de) todas as castas (*varna*); um rei que usa tal (propriedade) para si mesmo incorre na culpa de um ladrão.` },
        { id: 'cm-8-41', number: 'Verso 41', text: `(Um rei) que conhece a lei sagrada, deve inquirir sobre as leis das castas (*gati*), dos distritos, das guildas e das famílias, e (assim) estabelecer a lei peculiar de cada um.` },
        { id: 'cm-8-42', number: 'Verso 42', text: `Pois os homens que seguem as suas ocupações particulares e permanecem com o seu dever particular, tornam-se queridos pelas pessoas, embora possam viver a uma certa distância.` },
        { id: 'cm-8-43', number: 'Verso 43', text: `Nem o rei nem qualquer servo seu deverão eles próprios fazer com que um processo judicial seja iniciado, ou abafar um que tenha sido trazido (perante eles) por (algum) outro (homem).` },
        { id: 'cm-8-44', number: 'Verso 44', text: `Como um caçador rastreia o covil de um cervo (ferido) pelas gotas de sangue, assim mesmo o rei deve descobrir de que lado está a razão, por inferências (dos fatos).` },
        { id: 'cm-8-45', number: 'Verso 45', text: `Quando engajado em processos judiciais, ele deve prestar total atenção à verdade, ao objeto (da disputa), (e) a si mesmo, a seguir às testemunhas, ao lugar, ao tempo, e ao aspecto.` },
        { id: 'cm-8-46', number: 'Verso 46', text: `O que pode ter sido praticado pelos virtuosos, por tais homens duas vezes nascidos que são devotados à lei, isso ele deverá estabelecer como lei, se não for oposto aos (costumes dos) países, famílias e castas (*gati*).` },
        { id: 'cm-8-47', number: 'Verso 47', text: `Quando um credor processa (perante o rei) para a recuperação de dinheiro de um devedor, que ele faça o devedor pagar a quantia que o credor provar (ser devida).` },
        { id: 'cm-8-48', number: 'Verso 48', text: `Por quaisquer meios que um credor possa ser capaz de obter posse de sua propriedade, mesmo por esses meios pode ele forçar o devedor e fazê-lo pagar.` },
        { id: 'cm-8-49', number: 'Verso 49', text: `Por persuasão moral, por processo judicial, por gestão astuta, ou pelo procedimento habitual, um credor pode recuperar a propriedade emprestada; e em quinto lugar, pela força.` },
        { id: 'cm-8-50', number: 'Verso 50', text: `Um credor que por si mesmo recupera a sua propriedade do seu devedor, não deve ser culpado pelo rei por retomar o que é seu.` },
        { id: 'cm-8-51', number: 'Verso 51', text: `Mas aquele que nega uma dívida que é provada por boa evidência, ele deverá ordenar que pague tal dívida ao credor e uma pequena multa de acordo com as suas circunstâncias.` },
        { id: 'cm-8-52', number: 'Verso 52', text: `Na negação (de uma dívida) por um devedor a quem foi exigido no tribunal que a pagasse, o reclamante deve chamar (uma testemunha) que estava presente (quando o empréstimo foi feito), ou aduzir outras evidências.` },
        { id: 'cm-8-53', number: 'Verso 53', text: `(O autor) que chama uma testemunha não presente na transação, que retira as suas declarações, ou não percebe que as suas declarações (são) confusas ou contraditórias;` },
        { id: 'cm-8-54', number: 'Verso 54', text: `Ou que, tendo afirmado o que pretende provar, em seguida varia (o seu caso), ou que sendo questionado sobre um fato devidamente afirmado por ele mesmo não se mantém fiel a ele;` },
        { id: 'cm-8-55', number: 'Verso 55', text: `Ou que conversa com as testemunhas num local impróprio para tal conversa; ou que se recusa a responder a uma pergunta, adequadamente colocada, ou abandona (o tribunal);` },
        { id: 'cm-8-56', number: 'Verso 56', text: `Ou que, sendo ordenado a falar, não responde, ou não prova o que alegou; ou que não sabe qual é o primeiro (ponto), e qual o segundo, falha no seu processo.` },
        { id: 'cm-8-57', number: 'Verso 57', text: `Àquele também que diz 'Eu tenho testemunhas', e, sendo ordenado a produzi-las, não as produz, o juiz deve, por esses (mesmos) motivos, declarar ser destituído de ação.` },
        { id: 'cm-8-58', number: 'Verso 58', text: `Se um autor não falar, ele pode ser punido corporalmente ou multado de acordo com a lei; se (um réu) não pleitear dentro de três quinzenas, ele perdeu a sua causa.` },
        { id: 'cm-8-59', number: 'Verso 59', text: `No dobro daquela quantia que (um réu) falsamente nega ou sobre a qual (o autor) falsamente declara, deverão esses dois (homens) que ofendem a justiça ser multados pelo rei.` },
        { id: 'cm-8-60', number: 'Verso 60', text: `(Um réu) que, sendo trazido (ao tribunal) pelo credor, (e) sendo questionado, nega (a dívida), deverá ser condenado (por sua falsidade) por pelo menos três testemunhas (que devem depor) na presença do *Brahmana* (nomeado pelo) rei.` },
        { id: 'cm-8-61', number: 'Verso 61', text: `Eu declararei plenamente que tipo de homens pode ser feito testemunha em processos de credores, e de que maneira essas (testemunhas) devem fornecer (evidências) verdadeiras.` },
        { id: 'cm-8-62', number: 'Verso 62', text: `Chefes de família, homens com descendência masculina, e (habitantes) indígenas (do país, sejam eles) *Kshatriyas*, *Vaisyas*, ou *Sudras*, são competentes, quando chamados por um litigante, para dar evidências, e não quaisquer pessoas de forma alguma (qualquer que seja sua condição) exceto em casos de urgência.` },
        { id: 'cm-8-63', number: 'Verso 63', text: `Homens confiáveis de todas as (quatro) castas (*varna*) podem ser feitos testemunhas em processos judiciais, (homens) que conhecem (todo o seu) dever, e estão livres de cobiça; mas que ele rejeite aqueles (de um) caráter oposto.` },
        { id: 'cm-8-64', number: 'Verso 64', text: `Aqueles não devem ser feitos (testemunhas) que tenham interesse no processo, nem (amigos) íntimos, companheiros, e inimigos (das partes), nem (homens) anteriormente condenados (por perjúrio), nem (pessoas) sofrendo de doença (grave), nem (aqueles) corrompidos (por pecado mortal).` },
        { id: 'cm-8-65', number: 'Verso 65', text: `O rei não pode ser feito testemunha, nem mecânicos e atores, nem um *Srotriya*, nem um estudante do Veda, nem (um asceta) que tenha abandonado (toda) conexão (com o mundo),` },
        { id: 'cm-8-66', number: 'Verso 66', text: `Nem alguém totalmente dependente, nem alguém de má fama, nem um *Dasyu*, nem alguém que segue ocupações proibidas, nem um (homem) idoso, nem uma criança, nem um (homem sozinho), nem um homem das castas mais baixas, nem alguém deficiente nos órgãos dos sentidos,` },
        { id: 'cm-8-67', number: 'Verso 67', text: `Nem alguém extremamente aflito, nem alguém intoxicado, nem um louco, nem alguém atormentado pela fome ou pela sede, nem alguém oprimido pela fadiga, nem alguém atormentado pelo desejo, nem um homem furioso, nem um ladrão.` },
        { id: 'cm-8-68', number: 'Verso 68', text: `As mulheres devem dar evidências para as mulheres, e para os homens duas vezes nascidos homens duas vezes nascidos (do) mesmo (tipo), *Sudras* virtuosos para *Sudras*, e homens das castas mais baixas para os mais baixos.` },
        { id: 'cm-8-69', number: 'Verso 69', text: `Mas qualquer pessoa, seja quem for, que tenha conhecimento pessoal (de um ato cometido) nos aposentos internos (de uma casa), ou em uma floresta, ou de (um crime que cause) perda de vida, pode dar testemunho entre as partes.` },
        { id: 'cm-8-70', number: 'Verso 70', text: `Na falha (de testemunhas qualificadas, o testemunho) pode ser dado (em tais casos) por uma mulher, por uma criança, por um homem idoso, por um pupilo, por um parente, por um escravo, ou por um servo contratado.` },
        { id: 'cm-8-71', number: 'Verso 71', text: `Mas o (juiz) deve considerar o testemunho de crianças, de homens idosos e enfermos, que (têm tendência a) falar inverdades, como não confiável, da mesma forma que o de homens com mentes perturbadas.` },
        { id: 'cm-8-72', number: 'Verso 72', text: `Em todos os casos de violência, de roubo e adultério, de difamação e agressão, ele não deve examinar a (competência de) testemunhas (muito estritamente).` },
        { id: 'cm-8-73', number: 'Verso 73', text: `Num conflito de testemunhas o rei aceitará (como verdadeira) a evidência da maioria; se (as partes em conflito forem) iguais em número, (a d)aqueles distinguidos por boas qualidades; numa diferença entre (testemunhas igualmente) distinguidas, (a d)os melhores entre os duas vezes nascidos.` },
        { id: 'cm-8-74', number: 'Verso 74', text: `Evidência de acordo com o que foi de fato visto ou ouvido, é admissível; uma testemunha que fala a verdade nesses (casos), nem perde mérito espiritual nem riqueza.` },
        { id: 'cm-8-75', number: 'Verso 75', text: `Uma testemunha que depõe em uma assembleia de homens honrados (*Arya*) qualquer outra coisa que não o que viu ou ouviu, cai após a morte de cabeça no inferno e perde o céu.` },
        { id: 'cm-8-76', number: 'Verso 76', text: `Quando um homem (originalmente) não nomeado para ser uma testemunha vê ou ouve qualquer coisa e é (posteriormente) examinado a respeito, ele deve declarar (exatamente) como viu ou ouviu.` },
        { id: 'cm-8-77', number: 'Verso 77', text: `Um homem que é livre de cobiça pode ser (aceito como) testemunha; mas nem mesmo muitas mulheres puras, porque o entendimento das fêmeas é propenso a vacilar, nem mesmo muitos outros homens, que são maculados com o pecado.` },
        { id: 'cm-8-78', number: 'Verso 78', text: `O que as testemunhas declaram com bastante naturalidade, isso deve ser recebido em julgamentos; (depoimentos) diferindo disso, que eles fazem impropriamente, não têm valor para (os propósitos da) justiça.` },
        { id: 'cm-8-79', number: 'Verso 79', text: `Estando as testemunhas reunidas no tribunal na presença do autor e do réu, que o juiz as examine, exortando-as gentilmente da seguinte maneira:` },
        { id: 'cm-8-80', number: 'Verso 80', text: `'O que vocês sabem ter sido mutuamente transacionado nesta matéria entre os dois homens diante de nós, declarem tudo de acordo com a verdade; pois vocês são testemunhas nesta (causa).` },
        { id: 'cm-8-81', number: 'Verso 81', text: `'Uma testemunha que fala a verdade em seu testemunho, ganha (após a morte) as regiões mais excelentes (de bem-aventurança) e aqui (abaixo) fama insuperável; tal testemunho é reverenciado pelo (próprio) *Brahman*.` },
        { id: 'cm-8-82', number: 'Verso 82', text: `'Aquele que dá falso testemunho está firmemente atado pelos grilhões de Varuna, impotente durante cem existências; que (os homens, portanto) deem verdadeiro testemunho.` },
        { id: 'cm-8-83', number: 'Verso 83', text: `'Pela veracidade uma testemunha é purificada, através da veracidade o seu mérito cresce, a verdade deve, portanto, ser dita por testemunhas de todas as castas (*varna*).` },
        { id: 'cm-8-84', number: 'Verso 84', text: `'A própria Alma é a testemunha da Alma, e a Alma é o refúgio da Alma; não desprezes a tua própria Alma, a testemunha suprema dos homens.` },
        { id: 'cm-8-85', number: 'Verso 85', text: `'Os ímpios, de fato, dizem em seus corações, "Ninguém nos vê;" mas os deuses os veem distintamente, bem como o macho dentro de seus próprios peitos.` },
        { id: 'cm-8-86', number: 'Verso 86', text: `'O céu, a terra, as águas, (o macho no) coração, a lua, o sol, o fogo, Yama e o vento, a noite, os dois crepúsculos, e a justiça conhecem a conduta de todos os seres corpóreos.'` },
        { id: 'cm-8-87', number: 'Verso 87', text: `O (juiz), sendo purificado, pedirá no período da manhã às (testemunhas) duas vezes nascidas que (também foram) purificadas, (e ficarão) de frente para o norte ou para o leste, que deem falso testemunho na presença (de imagens) dos deuses e dos *Brahmanas*.` },
        { id: 'cm-8-88', number: 'Verso 88', text: `Que ele examine um *Brahmana* (começando com) 'Fale', um *Kshatriya* (começando com) 'Fale a verdade', um *Vaisya* (admoestando-o) pelas (mencionando suas) vacas, grãos, e ouro, um *Sudra* (ameaçando-o) com (a culpa de) todo crime que cause a perda de casta;` },
        { id: 'cm-8-89', number: 'Verso 89', text: `(Dizendo), 'Quaisquer que sejam os lugares (de tormento) designados (pelos sábios) ao matador de um *Brahmana*, ao assassino de mulheres e crianças, àquele que trai um amigo, e a um homem ingrato, esses serão a tua (porção), se tu falares falsamente.` },
        { id: 'cm-8-90', number: 'Verso 90', text: `'(A recompensa) de todas as ações meritórias que tu, bom homem, fizeste desde o teu nascimento, se tornará a parte dos cães, se em teu discurso te desviares da verdade.` },
        { id: 'cm-8-91', number: 'Verso 91', text: `'Se tu pensas, Ó amigo da virtude, a respeito de ti mesmo, "Estou sozinho", (sabe que) aquele sábio que testemunha todos os atos virtuosos e todos os crimes, reside sempre em teu coração.` },
        { id: 'cm-8-92', number: 'Verso 92', text: `'Se tu não estás em desacordo com aquele Yama divino, o filho de Vivasvat, que habita em teu coração, tu não precisas visitar nem o Ganges nem a (terra dos) Kurus.` },
        { id: 'cm-8-93', number: 'Verso 93', text: `'Nu e tosado, atormentado pela fome e pela sede, e privado da visão, deverá o homem que dá falso testemunho ir com um caco de cerâmica mendigar comida à porta do seu inimigo.` },
        { id: 'cm-8-94', number: 'Verso 94', text: `'De cabeça para baixo, nas trevas absolutas, tombará o homem pecador no inferno, aquele que, sendo interrogado em um inquérito judicial, responde falsamente a uma pergunta.` },
        { id: 'cm-8-95', number: 'Verso 95', text: `'Aquele homem que num tribunal (de justiça) dá um relato inverídico de uma transação (ou afirma um fato) do qual não foi testemunha ocular, assemelha-se a um homem cego que engole peixe com as espinhas.` },
        { id: 'cm-8-96', number: 'Verso 96', text: `'Os deuses não estão familiarizados com um homem melhor neste mundo do que ele, de quem a sua Alma consciente não tem desconfiança, quando ele dá testemunho.` },
        { id: 'cm-8-97', number: 'Verso 97', text: `'Aprende agora, Ó amigo, de uma enumeração na devida ordem, quantos parentes ele destrói que dá falso testemunho em vários casos particulares.` },
        { id: 'cm-8-98', number: 'Verso 98', text: `'Ele mata cinco por falso testemunho a respeito de gado (pequeno), ele mata dez por falso testemunho a respeito de vacas, ele mata cem por falsa evidência relativa a cavalos, e mil por falsa evidência relativa a homens.` },
        { id: 'cm-8-99', number: 'Verso 99', text: `'Falando falsamente em uma causa a respeito de ouro, ele mata os nascidos e os não nascidos; por falso testemunho a respeito de terras, ele mata tudo; cuida, portanto, do falso testemunho a respeito de terras.` },
        { id: 'cm-8-100', number: 'Verso 100', text: `'Eles declaram (que o falso testemunho) a respeito de água, a respeito do prazer carnal de mulheres, e a respeito de todas as gemas, produzidas na água, ou consistindo de pedras (é) igualmente (iníquo) como uma mentira a respeito de terra.` },
        { id: 'cm-8-101', number: 'Verso 101', text: `'Marcando bem todos os males (que são produzidos) pelo perjúrio, declara tu abertamente tudo como (tu o) ouviste ou viste.'` },
        { id: 'cm-8-102', number: 'Verso 102', text: `Os *Brahmanas* que cuidam de gado, que comercializam, que são mecânicos, atores (ou cantores), servos braçais ou usurários, o (juiz) deverá tratar como *Sudras*.` },
        { id: 'cm-8-103', number: 'Verso 103', text: `Em (alguns) casos, um homem que, embora saiba (serem os fatos) diferentes, dá tal (falso testemunho) de um motivo piedoso, não perde o céu; tal (evidência) eles chamam de o discurso dos deuses.` },
        { id: 'cm-8-104', number: 'Verso 104', text: `Sempre que a morte de um *Sudra*, de um *Vaisya*, de um *Kshatriya*, ou de um *Brahmana* fosse (causada) por uma declaração da verdade, uma falsidade pode ser falada; pois tal (falsidade) é preferível à verdade.` },
        { id: 'cm-8-105', number: 'Verso 105', text: `Tais (testemunhas) devem oferecer a Sarasvati oblações de arroz fervido (*karu*) que são sagradas para a deusa da fala, realizando (assim) a melhor penitência a fim de expiar a culpa dessa falsidade.` },
        { id: 'cm-8-106', number: 'Verso 106', text: `Ou tal (testemunha) pode oferecer de acordo com a regra, manteiga clarificada no fogo, recitando os textos *Kushmanda*, ou o *Rik*, sagrado a Varuna, 'Desamarra, Ó Varuna, o grilhão mais alto', ou os três versos dirigidos às Águas.` },
        { id: 'cm-8-107', number: 'Verso 107', text: `Um homem que, sem estar doente, não der testemunho em (casos de) empréstimos e afins dentro de três quinzenas (após a convocação), tornar-se-á responsável por toda a dívida e (pagará) uma décima parte do total (como uma multa ao rei).` },
        { id: 'cm-8-108', number: 'Verso 108', text: `A testemunha a quem, dentro de sete dias depois de ter dado testemunho, acontecer (um infortúnio devido a) doença, um incêndio, ou a morte de um parente, será compelida a pagar a dívida e uma multa.` },
        { id: 'cm-8-109', number: 'Verso 109', text: `Se duas (partes) disputarem sobre questões para as quais não há testemunhas disponíveis, e o (juiz) for incapaz de averiguar realmente a verdade, ele poderá fazer com que ela seja descoberta até mesmo por um juramento.` },
        { id: 'cm-8-110', number: 'Verso 110', text: `Tanto pelos grandes sábios quanto pelos deuses juramentos foram tomados com o propósito de (decidir questões) duvidosas; e Vasishtha mesmo jurou um juramento diante do rei (Sudas), o filho de Pigavana.` },
        { id: 'cm-8-111', number: 'Verso 111', text: `Que nenhum homem sábio faça um juramento falso, mesmo em uma questão insignificante; pois aquele que jura falsamente está perdido neste (mundo) e após a morte.` },
        { id: 'cm-8-112', number: 'Verso 112', text: `Nenhum crime, causando a perda de casta, é cometido por jurar (falsamente) a mulheres, aos objetos do desejo de alguém, em casamentos, por causa de forragem para uma vaca, ou de lenha, e a fim (de mostrar) favor a um *Brahmana*.` },
        { id: 'cm-8-113', number: 'Verso 113', text: `Que o (juiz) faça com que um *Brahmana* jure por sua veracidade, um *Kshatriya* pela sua carruagem ou o animal em que cavalga e por suas armas, um *Vaisya* pelas suas vacas, grãos, e ouro, e um *Sudra* por (imprecar sobre a sua própria cabeça a culpa) de todas as ofensas graves (*pataka*).` },
        { id: 'cm-8-114', number: 'Verso 114', text: `Ou o (juiz) pode fazer a (parte) carregar fogo ou mergulhar debaixo d'água, ou tocar separadamente as cabeças das suas esposas e filhos.` },
        { id: 'cm-8-115', number: 'Verso 115', text: `Aquele a quem o fogo ardente não queima, a quem a água não força a vir (rapidamente) para cima, quem não encontra infortúnio repentino, deve ser tido por inocente com base no (poder do) seu juramento.` },
        { id: 'cm-8-116', number: 'Verso 116', text: `Pois antigamente, quando Vatsa foi acusado pelo seu irmão mais novo, o fogo, o espião do mundo, não queimou sequer um cabelo (dele) em razão da sua veracidade.` },
        { id: 'cm-8-117', number: 'Verso 117', text: `Sempre que falso testemunho tenha sido dado em qualquer processo, que o (juiz) reverta o julgamento, e o que quer que tenha sido feito deve ser (considerado como) desfeito.` },
        { id: 'cm-8-118', number: 'Verso 118', text: `Evidência (dada) por cobiça, distração, terror, amizade, luxúria, ira, ignorância e criancice é declarada (ser) inválida.` },
        { id: 'cm-8-119', number: 'Verso 119', text: `Proporei em (devida) ordem as punições particulares para aquele que dá falso testemunho a partir de qualquer um desses motivos.` },
        { id: 'cm-8-120', number: 'Verso 120', text: `(Aquele que comete perjúrio) através da cobiça será multado em mil (*panas*), (aquele que o faz) através da distração, na menor multa; (se um homem o faz) por medo, duas multas médias devem ser pagas como penalidade, (se ele o faz) por amizade, quatro vezes o valor da menor (multa).` },
        { id: 'cm-8-121', number: 'Verso 121', text: `(Aquele que o faz) por luxúria, (pagará) dez vezes a menor multa, mas (aquele que o faz) por ira, três vezes a seguinte (ou segunda multa); (aquele que o faz) por ignorância, duas centenas inteiras, mas (aquele que o faz) por criancice, cem (*panas*).` },
        { id: 'cm-8-122', number: 'Verso 122', text: `Eles declaram que os sábios prescreveram estas multas para perjúrio, a fim de prevenir um fracasso da justiça, e a fim de restringir a injustiça.` },
        { id: 'cm-8-123', number: 'Verso 123', text: `Mas um rei justo deverá multar e banir (homens das) três castas (*varna*) (inferiores) que deram falso testemunho, mas um *Brahmana* ele deverá (apenas) banir.` },
        { id: 'cm-8-124', number: 'Verso 124', text: `Manu, o filho do Autoexistente (*Svayambhu*), nomeou dez lugares nos quais a punição pode ser (feita para cair) nos casos das três castas (*varna*) (inferiores); mas um *Brahmana* deverá partir ileso (do país).` },
        { id: 'cm-8-125', number: 'Verso 125', text: `(Estes são) o órgão genital, a barriga, a língua, as duas mãos, e em quinto lugar os dois pés, o olho, o nariz, as duas orelhas, assim como o corpo (inteiro).` },
        { id: 'cm-8-126', number: 'Verso 126', text: `Que o (rei), tendo plenamente averiguado o motivo, o momento e o local (da ofensa), e tendo considerado a capacidade (do criminoso de sofrer) e a (natureza do) crime, faça a punição recair sobre os que a merecem.` },
        { id: 'cm-8-127', number: 'Verso 127', text: `A punição injusta destrói a reputação entre os homens, e a fama (após a morte), e causa até no próximo mundo a perda do céu; que ele, portanto, evite (infligi-la).` },
        { id: 'cm-8-128', number: 'Verso 128', text: `Um rei que pune os que não o merecem, e não pune os que o merecem, traz grande infâmia sobre si mesmo e (após a morte) afunda no inferno.` },
        { id: 'cm-8-129', number: 'Verso 129', text: `Que ele puna primeiramente por (suave) admoestação, depois por (dura) repreensão, em terceiro lugar por uma multa, depois disso por castigo corporal.` },
        { id: 'cm-8-130', number: 'Verso 130', text: `Mas quando ele não puder restringir tais (infratores) mesmo por punição corporal, então que ele aplique a eles inclusive todos os quatro (modos conjuntamente).` },
        { id: 'cm-8-131', number: 'Verso 131', text: `Aqueles nomes técnicos de (certas quantidades de) cobre, prata e ouro, que são geralmente usados na terra para os fins das transações comerciais entre os homens, eu declararei plenamente.` },
        { id: 'cm-8-132', number: 'Verso 132', text: `O cisco muito pequeno que é visto quando o sol brilha através de uma fresta, eles declaram (ser) a menor de (todas as) quantidades e (ser chamado) de *trasarenu* (uma partícula flutuante de poeira).` },
        { id: 'cm-8-133', number: 'Verso 133', text: `Sabei (que) oito *trasarenus* (são iguais) em volume (a) uma *liksha* (o ovo de um piolho), três destas a um grão de mostarda preta (*ragasarshapa*), e três da última a uma semente de mostarda branca.` },
        { id: 'cm-8-134', number: 'Verso 134', text: `Seis grãos de mostarda branca são um grão de cevada de tamanho médio, e três grãos de cevada uma *krishnala* (*raktika*, ou baga de gunga); cinco *krishnalas* são uma *masha* (fava), e dezesseis destas um *suvarna*.` },
        { id: 'cm-8-135', number: 'Verso 135', text: `Quatro *suvarnas* são uma *pala*, e dez *palas* uma *dharana*; duas *krishnalas* (de prata), pesadas juntas, devem ser consideradas uma *mashaka* de prata.` },
        { id: 'cm-8-136', number: 'Verso 136', text: `Dezesseis destas fazem uma *dharana* de prata, ou *purana*; mas sabei (que) um *karsha* de cobre é um *karshapana*, ou *pana*.` },
        { id: 'cm-8-137', number: 'Verso 137', text: `Sabei (que) dez *dharanas* de prata fazem um *satamana*; quatro *suvarnas* devem ser considerados (iguais) em peso a um *nishka*.` },
        { id: 'cm-8-138', number: 'Verso 138', text: `Duzentos e cinquenta *panas* são declarados (como sendo) a primeira (ou mais baixa) multa, cinco (centos) são considerados como a média (ou intermediária), mas mil como a mais alta.` },
        { id: 'cm-8-139', number: 'Verso 139', text: `Uma dívida sendo admitida como devida, (o réu) pagará cinco no cento (como multa), se for negada (e provada) o dobro; esse é o ensinamento de Manu.` },
        { id: 'cm-8-140', number: 'Verso 140', text: `Um prestamista pode estipular como acréscimo de seu capital, pelo juro, aquele permitido por Vasishtha, e tomar mensalmente a octogésima parte de uma centena.` },
        { id: 'cm-8-141', number: 'Verso 141', text: `Ou, lembrando-se do dever dos homens bons, ele pode tomar dois no cento (por mês), pois quem toma dois no cento não se torna um pecador por lucro.` },
        { id: 'cm-8-142', number: 'Verso 142', text: `Apenas dois no cento, três, quatro, e cinco (e não mais), ele pode tomar como juro mensal de acordo com a ordem das castas (*varna*).` },
        { id: 'cm-8-143', number: 'Verso 143', text: `Mas se um penhor benéfico (isto é, do qual aufere lucro, foi dado), ele não receberá nenhum juro sobre o empréstimo; nem poderá ele, após manter (tal) penhor por muito tempo, dá-lo ou vendê-lo.` },
        { id: 'cm-8-144', number: 'Verso 144', text: `Um penhor (a ser mantido apenas) não deve ser usado à força, (o credor), ao usá-lo dessa forma, deverá abrir mão do seu juro (total), ou, (se foi estragado pelo uso) ele deverá satisfazer o (proprietário) (pagando-lhe) o preço original; de outro modo ele comete um roubo do penhor.` },
        { id: 'cm-8-145', number: 'Verso 145', text: `Nem um penhor nem um depósito podem ser perdidos por decurso de tempo; ambos são recuperáveis, embora tenham permanecido muito tempo (com o depositário).` },
        { id: 'cm-8-146', number: 'Verso 146', text: `Coisas usadas com o consentimento amigável, uma vaca, um camelo, um cavalo de montaria, e (um animal) entregue para ser domado, nunca são perdidos (para o dono).` },
        { id: 'cm-8-147', number: 'Verso 147', text: `(Mas em geral) qualquer (bens móveis) que o dono veja serem gozados por outros durante dez anos, ao passo que, embora presente, ele nada diz, tais (bens móveis) ele não deverá recuperar.` },
        { id: 'cm-8-148', number: 'Verso 148', text: `Se (o dono não for) um idiota nem um menor e se (os seus bens móveis) forem desfrutados (por outro) diante de seus olhos, estes se perdem para ele pela lei; o possuidor adverso deverá reter aquela propriedade.` },
        { id: 'cm-8-149', number: 'Verso 149', text: `Um penhor, um limite, a propriedade de crianças, um depósito (aberto), um depósito selado, mulheres, a propriedade do rei e a riqueza de um *Srotriya* não se perdem em consequência de desfrute (adverso).` },
        { id: 'cm-8-150', number: 'Verso 150', text: `O tolo que usa um penhor sem a permissão do proprietário, deverá abater metade do seu juro, como compensação por (tal) uso.` },
        { id: 'cm-8-151', number: 'Verso 151', text: `Em transações em dinheiro, os juros pagos de uma só vez (não em prestações) nunca deverão exceder o dobro (do capital principal); sobre grãos, frutas, lã ou pelo, (e) bestas de carga, não devem ser mais do que cinco vezes (o valor original).` },
        { id: 'cm-8-152', number: 'Verso 152', text: `Os juros estipulados além da taxa legal, sendo contra (a lei), não podem ser recuperados; eles chamam a isso de modo usurário (de emprestar); (o prestamista) não tem (em caso algum) direito a (mais de) cinco no cento.` },
        { id: 'cm-8-153', number: 'Verso 153', text: `Que ele não tome juros além do ano, nem os que não são aprovados, nem juros compostos, juros periódicos, juros estipulados e juros corporais.` },
        { id: 'cm-8-154', number: 'Verso 154', text: `Aquele que, incapaz de pagar uma dívida (no tempo fixado), deseja fazer um novo contrato, pode renovar o acordo, após pagar os juros devidos.` },
        { id: 'cm-8-155', number: 'Verso 155', text: `Se ele não puder pagar o dinheiro (devido como juros), ele pode inseri-lo no (acordo) renovado; ele deve pagar tantos juros quantos forem devidos.` },
        { id: 'cm-8-156', number: 'Verso 156', text: `Aquele que fez um contrato para transportar mercadorias em uma carruagem com rodas por dinheiro e concordou com um certo local ou tempo, não colherá essa recompensa, se não cumprir o local e o tempo (estipulados).` },
        { id: 'cm-8-157', number: 'Verso 157', text: `Qualquer que seja a taxa fixada por homens que são especialistas em viagens marítimas e capazes de calcular (o lucro) de acordo com o local, o tempo e os objetos (transportados), essa (tem força legal) em tais casos no que diz respeito ao pagamento (a ser feito).` },
        { id: 'cm-8-158', number: 'Verso 158', text: `O homem que se torna um fiador neste (mundo) para o comparecimento de um (devedor), e não o apresenta, deverá pagar a dívida com a sua própria propriedade.` },
        { id: 'cm-8-159', number: 'Verso 159', text: `Mas o dinheiro devido por um fiador, ou ociosamente prometido, ou perdido no jogo, ou devido por bebida alcoólica, ou o que resta não pago de uma multa e um imposto ou taxa, o filho (da parte que o deve) não será obrigado a pagar.` },
        { id: 'cm-8-160', number: 'Verso 160', text: `Esta regra recém-mencionada se aplicará ao caso de um fiador de comparecimento (apenas); se um fiador de pagamento vier a falecer, o (juiz) pode compelir até mesmo os seus herdeiros a quitar a dívida.` },
        { id: 'cm-8-161', number: 'Verso 161', text: `Por que motivo, então, é que após a morte de um fiador que não seja de pagamento, cujos assuntos são plenamente conhecidos, o credor pode (em alguns casos) posteriormente exigir a dívida (dos herdeiros)?` },
        { id: 'cm-8-162', number: 'Verso 162', text: `Se o fiador havia recebido dinheiro (daquele para quem prestou fiança) e tinha dinheiro suficiente (para pagar), então (o herdeiro daquele) que o recebeu, deverá pagar (a dívida) da sua propriedade; essa é a regra estabelecida.` },
        { id: 'cm-8-163', number: 'Verso 163', text: `Um contrato feito por uma pessoa intoxicada, ou insana, ou gravemente perturbada (por doença e assim por diante), ou totalmente dependente, por uma criança ou um homem muito idoso, ou por uma (parte) não autorizada, é inválido.` },
        { id: 'cm-8-164', number: 'Verso 164', text: `Aquele acordo que foi feito contrariando a lei ou o costume estabelecido (dos virtuosos), não pode ter força legal, ainda que seja estabelecido (por provas).` },
        { id: 'cm-8-165', number: 'Verso 165', text: `Uma hipoteca ou venda fraudulenta, uma doação ou aceitação fraudulenta, e (qualquer transação) onde se detecte fraude, o (juiz) deverá declarar nula e sem efeito.` },
        { id: 'cm-8-166', number: 'Verso 166', text: `Se o devedor estiver morto e (o dinheiro emprestado) foi gasto para a família, deve ser pago pelos parentes da sua própria propriedade, mesmo que estejam divididos.` },
        { id: 'cm-8-167', number: 'Verso 167', text: `Caso mesmo uma pessoa totalmente dependente faça um contrato em benefício da família, o mestre (da casa), quer (vivendo) em seu próprio país ou no exterior, não deverá rescindi-lo.` },
        { id: 'cm-8-168', number: 'Verso 168', text: `O que é dado pela força, o que é desfrutado pela força, também o que foi feito escrever pela força, e todas as outras transações feitas pela força, Manu declarou nulas.` },
        { id: 'cm-8-169', number: 'Verso 169', text: `Três sofrem por causa de outros: testemunhas, um fiador e juízes; mas quatro enriquecem (através de outros): um *Brahmana*, um prestamista, um mercador e um rei.` },
        { id: 'cm-8-170', number: 'Verso 170', text: `Nenhum rei, por mais indigente que seja, deverá tomar qualquer coisa que não deva ser tomada, nem deverá, por mais rico que seja, recusar-se a tomar aquilo que deve tomar, por menor que seja.` },
        { id: 'cm-8-171', number: 'Verso 171', text: `Em consequência de tomar o que não deve ser tomado, ou de recusar o que deve ser recebido, um rei será acusado de fraqueza e perecerá neste (mundo) e após a morte.` },
        { id: 'cm-8-172', number: 'Verso 172', text: `Ao tomar o que lhe é devido, ao evitar a confusão das castas (*varna*), e ao proteger os fracos, o poder do rei cresce, e ele prospera neste (mundo) e após a morte.` },
        { id: 'cm-8-173', number: 'Verso 173', text: `Que o príncipe, portanto, como Yama, não prestando atenção aos seus próprios gostos e desgostos, comporte-se exatamente como Yama, suprimindo a sua raiva e controlando a si mesmo.` },
        { id: 'cm-8-174', number: 'Verso 174', text: `Mas aquele rei mal-intencionado que em sua tolice decide as causas injustamente, os seus inimigos logo o subjugam.` },
        { id: 'cm-8-175', number: 'Verso 175', text: `Se, subjugando o amor e o ódio, ele decide as causas de acordo com a lei, (os corações de) seus súditos voltam-se para ele como os rios (correm) para o oceano.` },
        { id: 'cm-8-176', number: 'Verso 176', text: `(O devedor) que se queixa ao rei que o seu credor recupera (a dívida) independentemente (do tribunal), deverá ser compelido pelo rei a pagar (como multa) um quarto (da quantia) e ao seu (credor) o dinheiro (devido).` },
        { id: 'cm-8-177', number: 'Verso 177', text: `Mesmo pelo trabalho (pessoal) deverá o devedor reparar (o que deve) ao seu credor, se for da mesma casta ou de uma inferior; mas um (devedor) de uma casta superior deverá pagá-la gradualmente (quando ganhar alguma coisa).` },
        { id: 'cm-8-178', number: 'Verso 178', text: `De acordo com estas regras, que o rei decida equitativamente entre os homens que disputam entre si as questões que são provadas por testemunhas e (outras) evidências.` },
        { id: 'cm-8-179', number: 'Verso 179', text: `Um homem sensato deve fazer um depósito (apenas) com uma pessoa de (boa) família, de boa conduta, bem familiarizada com a lei, veraz, tendo muitos parentes, rica e honrada (*arya*).` },
        { id: 'cm-8-180', number: 'Verso 180', text: `Da mesma maneira que uma pessoa depositar qualquer coisa nas mãos de outra, da mesma maneira deve a mesma coisa ser recebida de volta (pelo dono); assim como foi a entrega, (assim deve ser) a devolução.` },
        { id: 'cm-8-181', number: 'Verso 181', text: `Aquele que não restitui o seu depósito ao depositante a seu pedido, pode ser julgado pelo juiz na ausência do depositante.` },
        { id: 'cm-8-182', number: 'Verso 182', text: `Na falta de testemunhas, que o (juiz) deposite de fato ouro com aquele (réu) sob algum pretexto ou outro através de espiões de idade e aparência adequadas (e depois exija-o de volta).` },
        { id: 'cm-8-183', number: 'Verso 183', text: `Se o (réu) o restituir na maneira e forma em que foi confiado, não há nada (dessa descrição) em suas mãos pelo que os outros o acusam.` },
        { id: 'cm-8-184', number: 'Verso 184', text: `Mas se ele não restituir aquele ouro, como deve, àqueles (espiões), então ele será compelido pela força a restituir ambos (os depósitos); essa é uma regra estabelecida da lei.` },
        { id: 'cm-8-185', number: 'Verso 185', text: `Um depósito aberto ou selado nunca deve ser devolvido a um parente próximo (do depositante durante a vida deste último); pois se (o destinatário) morrer (sem os entregar), eles estão perdidos, mas se ele não morrer, eles não estão perdidos.` },
        { id: 'cm-8-186', number: 'Verso 186', text: `Mas (um depositário) que por sua própria vontade os devolve a um parente próximo de um (depositante) falecido, não deve ser importunado (sobre eles) pelo rei ou pelos parentes do depositante.` },
        { id: 'cm-8-187', number: 'Verso 187', text: `E (em casos duvidosos) ele deve tentar obter aquele objeto por meios amigáveis, sem (recorrer a) artifícios, ou tendo investigado a conduta (do depositário), ele deve resolver (a questão) com meios gentis.` },
        { id: 'cm-8-188', number: 'Verso 188', text: `Tal é a regra para reaver todos esses depósitos abertos; no caso de um depósito selado (o depositário) não incorrerá em (censura), a menos que tenha tirado alguma coisa.` },
        { id: 'cm-8-189', number: 'Verso 189', text: `(Um depósito) que tenha sido roubado por ladrões ou levado pela água ou queimado pelo fogo, (o depositário) não deverá reparar, a menos que tenha tomado parte dele (para si mesmo).` },
        { id: 'cm-8-190', number: 'Verso 190', text: `Aquele que se apropria de um depósito e aquele (que o pede) sem o ter feito, o (juiz) deverá provar por todos (os tipos de) meios, e pelos juramentos prescritos no Veda.` },
        { id: 'cm-8-191', number: 'Verso 191', text: `Aquele que não devolve um depósito e aquele que exige o que nunca confiou devem ambos ser punidos como ladrões, ou ser compelidos a pagar uma multa igual (ao valor do objeto retido ou reivindicado).` },
        { id: 'cm-8-192', number: 'Verso 192', text: `O rei deve compelir aquele que não restitui um depósito aberto, e de igual modo aquele que retém um depósito selado, a pagar uma multa igual (ao seu valor).` },
        { id: 'cm-8-193', number: 'Verso 193', text: `Aquele homem que por falsos pretextos se apoderar da propriedade de outrem, deverá ser punido publicamente por vários (modos de) castigo corporal (ou capital), juntamente com os seus cúmplices.` },
        { id: 'cm-8-194', number: 'Verso 194', text: `Se um depósito de uma descrição ou quantidade particular for confiado por qualquer pessoa na presença de um número (de testemunhas), ele deve ser conhecido por ser daquela (descrição e quantidade) particular; (o depositário) que fizer uma falsa declaração (a respeito disso) está sujeito a uma multa.` },
        { id: 'cm-8-195', number: 'Verso 195', text: `Mas se qualquer coisa for entregue ou recebida privativamente, ela deve ser devolvida privativamente; como foi o depósito, (assim deve ser) a devolução.` },
        { id: 'cm-8-196', number: 'Verso 196', text: `Assim que o rei decida (causas) a respeito de um depósito e um empréstimo amigável (para uso) sem mostrar rigor (indevido) ao depositário.` },
        { id: 'cm-8-197', number: 'Verso 197', text: `Se alguém vender a propriedade de outro homem, sem ser o dono e sem o consentimento do dono, o (juiz) não deverá admitir aquele que é um ladrão, embora ele não possa se considerar como um ladrão, como testemunha (em caso algum).` },
        { id: 'cm-8-198', number: 'Verso 198', text: `Se o (infrator) for um parente (do proprietário), ele deverá ser multado em seiscentos *panas*; se ele não for um parente, nem tiver qualquer desculpa, ele será culpado de roubo.` },
        { id: 'cm-8-199', number: 'Verso 199', text: `Uma doação ou venda, feita por qualquer outra pessoa que não o dono, deve ser considerada como nula e sem efeito, de acordo com a regra nos procedimentos judiciais.` },
        { id: 'cm-8-200', number: 'Verso 200', text: `Onde a posse é evidente, mas nenhum título é percebido, ali o título (será) uma prova (de propriedade), não a posse; tal é a regra estabelecida.` },
        { id: 'cm-8-201', number: 'Verso 201', text: `Aquele que obtém um bem móvel no mercado diante de um número (de testemunhas), adquire esse bem móvel com um título legal claro por compra.` },
        { id: 'cm-8-202', number: 'Verso 202', text: `Se o (vendedor) original não for apresentável, (o comprador) sendo exculpado por uma venda pública, deve ser dispensado pelo rei sem punição, mas (o proprietário anterior) que perdeu o bem móvel deverá recebê-lo (de volta do comprador).` },
        { id: 'cm-8-203', number: 'Verso 203', text: `Uma mercadoria misturada com outra não deve ser vendida (como pura), nem uma ruim (como boa), nem menos (do que a quantidade ou peso adequados), nem nada que não esteja à mão ou que esteja oculto.` },
        { id: 'cm-8-204', number: 'Verso 204', text: `Se, depois que uma donzela foi mostrada, outra for dada ao noivo, ele pode casar-se com ambas pelo mesmo preço; assim ordenou Manu.` },
        { id: 'cm-8-205', number: 'Verso 205', text: `Aquele que dá (uma donzela em casamento), tendo primeiro declarado abertamente os seus defeitos, quer ela seja insana, ou afligida por lepra, ou tenha perdido a virgindade, não está sujeito a punição.` },
        { id: 'cm-8-206', number: 'Verso 206', text: `Se um sacerdote oficiante, escolhido para realizar um sacrifício, abandona a sua obra, apenas uma parte (da taxa) em proporção à obra (feita) ser-lhe-á dada por aqueles que trabalham com ele.` },
        { id: 'cm-8-207', number: 'Verso 207', text: `Mas aquele que abandona a sua obra depois de as taxas sacrificais terem sido dadas, deverá obter a sua parte integral e mandar executar (o que resta) por outro (sacerdote).` },
        { id: 'cm-8-208', number: 'Verso 208', text: `Mas se taxas (específicas) são ordenadas para as várias partes de um rito, deverá ele (que executa a parte) recebê-las, ou todos eles deverão partilhá-las?` },
        { id: 'cm-8-209', number: 'Verso 209', text: `O sacerdote *Adhvaryu* tomará a carruagem, e o *Brahman* no acender dos fogos (*Agnyadhana*) um cavalo, o sacerdote *Hotri* também tomará um cavalo, e o *Udgatri* a carroça, (usada) quando (o Soma) é comprado.` },
        { id: 'cm-8-210', number: 'Verso 210', text: `Os (quatro) sacerdotes principais entre todos (os dezesseis), que têm direito a uma metade, receberão uma porção (da taxa), os próximos (quatro) a metade disso, o grupo com direito a uma terça parte, um terço, e aqueles com direito a uma quarta, um quarto.` },
        { id: 'cm-8-211', number: 'Verso 211', text: `Pela aplicação destes princípios a distribuição das partes deve ser feita entre aqueles homens que aqui (abaixo) realizam o seu trabalho em conjunto.` },
        { id: 'cm-8-212', number: 'Verso 212', text: `Caso seja dado (ou prometido) dinheiro para um propósito piedoso por um homem a outro que o pede, a doação será nula, se o (dinheiro for) posteriormente não (usado) da maneira (declarada).` },
        { id: 'cm-8-213', number: 'Verso 213', text: `Mas se o (destinatário) por orgulho ou ganância tentar forçar (o cumprimento da promessa), ele será compelido pelo rei a pagar um *suvarna* como expiação pelo seu roubo.` },
        { id: 'cm-8-214', number: 'Verso 214', text: `Assim, a subtração legal de uma doação foi plenamente explicada; em seguida proporei (a lei para) o não pagamento de salários.` },
        { id: 'cm-8-215', number: 'Verso 215', text: `Um (servo ou trabalhador) contratado que, sem estar doente, por orgulho deixa de realizar o seu trabalho de acordo com o acordo, será multado em oito *krishnalas* e nenhum salário lhe será pago.` },
        { id: 'cm-8-216', number: 'Verso 216', text: `Mas (se ele estiver realmente) doente, (e) após a recuperação realizar (o seu trabalho) de acordo com o acordo original, ele deverá receber os seus salários mesmo após (o decurso de) um tempo muito longo.` },
        { id: 'cm-8-217', number: 'Verso 217', text: `Mas se ele, seja doente ou bem, não (executar ou) não mandar executar (por outros) o seu trabalho de acordo com o seu acordo, os salários para esse trabalho não lhe serão dados, mesmo (se estiver apenas) ligeiramente incompleto.` },
        { id: 'cm-8-218', number: 'Verso 218', text: `Assim a lei para o não pagamento de salários foi completamente declarada; em seguida explicarei a lei a respeito de homens que quebram um acordo.` },
        { id: 'cm-8-219', number: 'Verso 219', text: `Se um homem pertencente a uma corporação que habita uma aldeia ou um distrito, após jurar um acordo, o quebrar por avareza, (o rei) deverá bani-lo de seu reino,` },
        { id: 'cm-8-220', number: 'Verso 220', text: `E tendo aprisionado tal violador de um acordo, ele o compelirá a pagar seis *nishkas*, (cada um de) quatro *suvarnas*, e um *satamana* de prata.` },
        { id: 'cm-8-221', number: 'Verso 221', text: `Um rei justo deverá aplicar esta lei de multas em aldeias e castas (*gati*) àqueles que quebrarem um acordo.` },
        { id: 'cm-8-222', number: 'Verso 222', text: `Se alguém neste (mundo), após comprar ou vender qualquer coisa, se arrepender (da sua barganha), ele pode devolver ou pegar (de volta) aquele bem móvel dentro de dez dias.` },
        { id: 'cm-8-223', number: 'Verso 223', text: `Mas depois (do lapso de) dez dias ele não pode nem dar nem mandá-lo ser dado (de volta); tanto aquele que o pega (de volta) quanto aquele que o dá (de volta, exceto por consentimento) serão multados pelo rei em seiscentos (*panas*).` },
        { id: 'cm-8-224', number: 'Verso 224', text: `Mas o próprio rei imporá uma multa de noventa e seis *panas* àquele que der uma donzela com defeito (a um pretendente) sem o informar (do defeito).` },
        { id: 'cm-8-225', number: 'Verso 225', text: `Mas aquele homem que, por malícia, disser de uma donzela: 'Ela não é donzela', será multado em cem (*panas*), se não puder provar a sua falha.` },
        { id: 'cm-8-226', number: 'Verso 226', text: `Os textos nupciais aplicam-se exclusivamente a virgens, (e) em parte alguma entre os homens a fêmeas que tenham perdido a sua virgindade, pois tais (fêmeas) estão excluídas de cerimônias religiosas.` },
        { id: 'cm-8-227', number: 'Verso 227', text: `Os textos nupciais são uma prova certa (de que uma donzela foi feita uma esposa legal); mas os instruídos devem saber que eles (e a cerimônia de casamento estão completos com o sétimo passo (da noiva ao redor do fogo sagrado).` },
        { id: 'cm-8-228', number: 'Verso 228', text: `Se alguém neste (mundo) se arrepender de qualquer transação concluída, (o rei) deverá mantê-lo no caminho da retidão de acordo com as regras dadas acima.` },
        { id: 'cm-8-229', number: 'Verso 229', text: `Declararei plenamente de acordo com a verdadeira lei (as regras relativas a) as disputas, (surgidas) das transgressões de donos de gado e de pastores.` },
        { id: 'cm-8-230', number: 'Verso 230', text: `Durante o dia a responsabilidade pela segurança (do gado recai) sobre o pastor, durante a noite sobre o proprietário, (desde que estejam) em sua casa; (se for) de outro modo, o pastor será responsável (por eles também durante a noite).` },
        { id: 'cm-8-231', number: 'Verso 231', text: `Um pastor contratado que é pago com leite, pode ordenhar com o consentimento do dono a melhor (vaca) de cada dez; tal será a sua remuneração se não forem pagos (outros) salários.` },
        { id: 'cm-8-232', number: 'Verso 232', text: `O pastor sozinho deverá compensar (a perda de um animal) desgarrado, destruído por vermes, morto por cães ou (por cair) num poço, se não se esforçou devidamente (para impedi-lo).` },
        { id: 'cm-8-233', number: 'Verso 233', text: `Mas por (um animal) roubado por ladrões, embora ele tenha dado o alarme, o pastor não deverá pagar, desde que dê o aviso ao seu senhor no lugar e tempo adequados.` },
        { id: 'cm-8-234', number: 'Verso 234', text: `Se o gado morrer, que ele leve ao seu senhor as suas orelhas, pele, caudas, bexigas, tendões e a bile concreta amarela, e que ele aponte as suas marcas particulares.` },
        { id: 'cm-8-235', number: 'Verso 235', text: `Mas se cabras ou ovelhas forem cercadas por lobos e o pastor não se apressar (em sua assistência), ele será responsável por qualquer (animal) que um lobo possa atacar e matar.` },
        { id: 'cm-8-236', number: 'Verso 236', text: `Mas se eles, mantidos em ordem (adequada), pastarem juntos na floresta, e um lobo, saltando repentinamente sobre um deles, o matar, o pastor não terá nesse caso nenhuma responsabilidade.` },
        { id: 'cm-8-237', number: 'Verso 237', text: `Em todos os lados de uma aldeia, um espaço, de cem *dhanus* ou três lançamentos de *samya* (em largura), será reservado (para pastagem), e três vezes (esse espaço) ao redor de uma cidade.` },
        { id: 'cm-8-238', number: 'Verso 238', text: `Se o gado causar danos a plantações não cercadas naquele (terreno comunal), o rei não deverá nesse caso punir os pastores.` },
        { id: 'cm-8-239', number: 'Verso 239', text: `(O dono do campo) deverá fazer ali uma cerca sobre a qual um camelo não possa espiar, e tapar cada brecha através da qual um cão ou um javali possa enfiar a sua cabeça.` },
        { id: 'cm-8-240', number: 'Verso 240', text: `(Se o gado fizer estragos) num campo cercado próximo de uma rodovia ou perto de uma aldeia, o pastor será multado em cem (*panas*); (mas o gado), desacompanhado de um pastor, (o vigia no campo) deverá expulsar.` },
        { id: 'cm-8-241', number: 'Verso 241', text: `(Por danos) em outros campos (cada cabeça de) gado deverá (pagar uma multa de um (*pana*) e um quarto, e em todos (os casos o valor da) plantação (destruída) será compensado ao dono do campo; essa é a regra estabelecida.` },
        { id: 'cm-8-242', number: 'Verso 242', text: `Mas Manu declarou que nenhuma multa será paga por (danos causados por) uma vaca dentro de dez dias após o seu parto, por touros e por gado sagrado aos deuses, sejam eles assistidos por um pastor ou não.` },
        { id: 'cm-8-243', number: 'Verso 243', text: `Se (as colheitas forem destruídas por) culpa (do próprio) lavrador, a multa deverá ser dez vezes maior do que a parte (do rei); mas a multa (será) apenas metade desse valor se (a culpa recair) sobre os servos e o agricultor não tiver tido conhecimento disso.` },
        { id: 'cm-8-244', number: 'Verso 244', text: `A estas regras um rei justo deverá se ater em (todos os casos de) transgressões por mestres, seu gado e pastores.` },
        { id: 'cm-8-245', number: 'Verso 245', text: `Se surgir uma disputa entre duas aldeias a respeito de um limite, o rei estabelecerá os limites no mês de *Gyaishtha*, quando os marcos são mais distintamente visíveis.` },
        { id: 'cm-8-246', number: 'Verso 246', text: `Que ele marque os limites (por) árvores, (ex.) *Nyagrodhas*, *Asvatthas*, *Kimsukas*, árvores de algodão, *Salas*, palmeiras de Palmyra e árvores com seiva leitosa,` },
        { id: 'cm-8-247', number: 'Verso 247', text: `Por arbustos em grupos, bambus de diferentes tipos, *Samis*, trepadeiras e montes de terra erguidos, juncos, matagais de *Kubgaka*; assim o limite não será esquecido.` },
        { id: 'cm-8-248', number: 'Verso 248', text: `Tanques, poços, cisternas e fontes devem ser construídos onde os limites se encontram, assim como templos,` },
        { id: 'cm-8-249', number: 'Verso 249', text: `E como ele verá que através da ignorância dos homens sobre os limites ocorrem constantemente transgressões no mundo, que ele ordene que se façam outras marcas ocultas para os limites,` },
        { id: 'cm-8-250', number: 'Verso 250', text: `Pedras, ossos, pelos de vaca, palha, cinzas, cacos de cerâmica, esterco seco de vaca, tijolos, brasas, seixos e areia,` },
        { id: 'cm-8-251', number: 'Verso 251', text: `E quaisquer outras coisas de tipo semelhante que a terra não corroa mesmo após muito tempo, essas ele deverá ordenar que sejam enterradas onde um limite se une (ao outro).` },
        { id: 'cm-8-252', number: 'Verso 252', text: `Por estes sinais, por longa posse contínua e por correntes de água fluindo constantemente, o rei averiguará o limite (da terra) de duas partes em disputa.` },
        { id: 'cm-8-253', number: 'Verso 253', text: `Se houver dúvida mesmo após a inspeção das marcas, a resolução de uma disputa sobre limites dependerá de testemunhas.` },
        { id: 'cm-8-254', number: 'Verso 254', text: `As testemunhas, (dando evidência) a respeito de um limite, deverão ser examinadas concernente aos marcos na presença da multidão dos aldeões e também dos dois litigantes.` },
        { id: 'cm-8-255', number: 'Verso 255', text: `Conforme eles, sendo questionados, decidirem unanimemente, da mesma forma ele deverá registrar o limite (por escrito), juntamente com os seus nomes.` },
        { id: 'cm-8-256', number: 'Verso 256', text: `Que eles, colocando terra sobre as suas cabeças, usando guirlandas (de flores vermelhas) e vestidos vermelhos, sendo jurados cada um (pelas recompensas dos) seus atos meritórios, estabeleçam (o limite) de acordo com a verdade.` },
        { id: 'cm-8-257', number: 'Verso 257', text: `Se eles determinarem (o limite) da maneira declarada, eles são inocentes (sendo) testemunhas verazes; mas se o determinarem injustamente, eles deverão ser compelidos a pagar uma multa de duzentos (*panas*).` },
        { id: 'cm-8-258', number: 'Verso 258', text: `Na falta de testemunhas (das duas aldeias, homens das) quatro aldeias vizinhas, que sejam puros, farão (como testemunhas) uma decisão a respeito do limite na presença do rei.` },
        { id: 'cm-8-259', number: 'Verso 259', text: `Na falta de vizinhos (que sejam) habitantes originais (do país e possam ser) testemunhas com respeito ao limite, (o rei) pode ouvir a evidência até mesmo dos seguintes habitantes da floresta.` },
        { id: 'cm-8-260', number: 'Verso 260', text: `(A saber) caçadores, passarinheiros, pastores, pescadores, cavadores de raízes, apanhadores de cobras, respigadores e outros silvícolas.` },
        { id: 'cm-8-261', number: 'Verso 261', text: `Conforme eles, sendo examinados, declarem ser as marcas para o encontro dos limites, da mesma forma o rei justamente fará com que sejam fixadas entre as duas aldeias.` },
        { id: 'cm-8-262', number: 'Verso 262', text: `A decisão sobre os marcos de limites de campos, poços, tanques, de jardins e casas depende da (evidência dos) vizinhos.` },
        { id: 'cm-8-263', number: 'Verso 263', text: `Caso os vizinhos deem falso testemunho, quando os homens disputam sobre um marco de limite, o rei fará cada um deles pagar a multa média como penalidade.` },
        { id: 'cm-8-264', number: 'Verso 264', text: `Aquele que por intimidação se apodera de uma casa, um tanque, um jardim, ou um campo, será multado em quinhentos (*panas*); (se invadiu) por ignorância, a multa (será) duzentos (*panas*).` },
        { id: 'cm-8-265', number: 'Verso 265', text: `Se o limite não puder ser averiguado (por nenhuma evidência), que um rei justo com (a intenção de) beneficiá-los (todos), ele mesmo atribua (sua) terra (a cada um); essa é a regra estabelecida.` },
        { id: 'cm-8-266', number: 'Verso 266', text: `Assim a lei para decidir (disputas) de limite foi plenamente declarada, em seguida proporei a (maneira de) decidir (casos de) difamação.` },
        { id: 'cm-8-267', number: 'Verso 267', text: `Um *Kshatriya*, tendo difamado um *Brahmana*, será multado em cem (*panas*); um *Vaisya* cento e cinquenta ou duzentos; um *Sudra* sofrerá punição corporal.` },
        { id: 'cm-8-268', number: 'Verso 268', text: `Um *Brahmana* será multado em cinquenta (*panas*) por difamar um *Kshatriya*; no (caso de) um *Vaisya* a multa será de vinte e cinco (*panas*); no (caso de) um *Sudra* doze.` },
        { id: 'cm-8-269', number: 'Verso 269', text: `Para ofensas de homens duas vezes nascidos contra os de casta (*varna*) igual, a multa será também de doze (*panas*); para discursos que não deveriam ser proferidos, isso (e toda multa será) o dobro.` },
        { id: 'cm-8-270', number: 'Verso 270', text: `Um homem nascido uma vez (um *Sudra*), que insulta um homem duas vezes nascido com grosserias injuriosas, terá a sua língua cortada; pois ele é de origem inferior.` },
        { id: 'cm-8-271', number: 'Verso 271', text: `Se ele menciona os nomes e as castas (*gati*) dos (duas vezes nascidos) com contumélia, um prego de ferro, de dez dedos de comprimento, deverá ser enfiado em brasa na sua boca.` },
        { id: 'cm-8-272', number: 'Verso 272', text: `Se ele arrogantemente ensina aos *Brahmanas* o seu dever, o rei mandará deitar óleo a ferver na sua boca e nas suas orelhas.` },
        { id: 'cm-8-273', number: 'Verso 273', text: `Aquele que por arrogância faz falsas declarações a respeito do aprendizado (de um companheiro de casta), o seu país, a sua casta (*gati*), ou os ritos pelos quais o seu corpo foi santificado, será compelido a pagar uma multa de duzentos (*panas*).` },
        { id: 'cm-8-274', number: 'Verso 274', text: `Aquele que mesmo de acordo com os verdadeiros fatos chama (desdenhosamente) outro homem de caolho, coxo, ou (nomes) semelhantes, será multado em pelo menos um *karshapana*.` },
        { id: 'cm-8-275', number: 'Verso 275', text: `Aquele que difama a sua mãe, o seu pai, a sua esposa, o seu irmão, o seu filho, ou o seu professor, e aquele que não dá a passagem ao seu preceptor, será compelido a pagar cem (*panas*).` },
        { id: 'cm-8-276', number: 'Verso 276', text: `(Por abuso mútuo) por um *Brahmana* e um *Kshatriya* uma multa deve ser imposta por um (rei) perspicaz, ao *Brahmana* a menor multa, mas ao *Kshatriya* a média.` },
        { id: 'cm-8-277', number: 'Verso 277', text: `Um *Vaisya* e um *Sudra* devem ser punidos exatamente da mesma maneira de acordo com as suas respectivas castas, mas a língua (do *Sudra*) não será cortada; essa é a decisão.` },
        { id: 'cm-8-278', number: 'Verso 278', text: `Assim as regras de punição (aplicáveis aos casos) de difamação foram verdadeiramente declaradas; em seguida proporei a decisão (dos casos) de agressão.` },
        { id: 'cm-8-279', number: 'Verso 279', text: `Com qualquer membro que um homem de uma casta inferior machuque (um homem das três) (castas) mais altas, até mesmo esse membro deverá ser cortado; esse é o ensinamento de Manu.` },
        { id: 'cm-8-280', number: 'Verso 280', text: `Aquele que levanta a mão ou um pedaço de pau, terá a sua mão cortada; aquele que em raiva chuta com o pé, terá o seu pé cortado.` },
        { id: 'cm-8-281', number: 'Verso 281', text: `Um homem de casta inferior que tenta colocar a si mesmo no mesmo assento com um homem de uma casta superior, deverá ser marcado no seu quadril e banido, ou (o rei) mandará que lhe cortem as nádegas.` },
        { id: 'cm-8-282', number: 'Verso 282', text: `Se por arrogância ele cospe (num superior), o rei mandará que ambos os seus lábios sejam cortados; se urinar (nele), o pênis; se der puns (contra ele), o ânus.` },
        { id: 'cm-8-283', number: 'Verso 283', text: `Se ele agarra o cabelo (de um superior), que o (rei) sem hesitação lhe corte as mãos, igualmente (se o pegar) pelos pés, pela barba, pelo pescoço ou pelo escroto.` },
        { id: 'cm-8-284', number: 'Verso 284', text: `Aquele que rompe a pele (de um igual) ou tira sangue (dele) será multado em cem (*panas*), aquele que corta um músculo seis *nishkas*, aquele que quebra um osso será banido.` },
        { id: 'cm-8-285', number: 'Verso 285', text: `De acordo com a utilidade das diversas (espécies de) árvores, uma multa deve ser infligida por feri-las; essa é a regra estabelecida.` },
        { id: 'cm-8-286', number: 'Verso 286', text: `Se um golpe é desferido contra homens ou animais a fim de (causar-lhes) dor, (o juiz) infligirá uma multa proporcional à quantidade de dor (causada).` },
        { id: 'cm-8-287', number: 'Verso 287', text: `Se um membro for machucado, uma ferida (for causada), ou sangue (fluir, o agressor) será obrigado a pagar (àquele que sofreu) as despesas da cura, ou o total (tanto a multa usual quanto as despesas da cura como) multa (ao rei).` },
        { id: 'cm-8-288', number: 'Verso 288', text: `Aquele que danifica os bens de outro, seja intencional ou não intencionalmente, dará satisfação ao (dono) e pagará ao rei uma multa igual ao (dano).` },
        { id: 'cm-8-289', number: 'Verso 289', text: `No caso de (dano causado a) couro, ou a utensílios de couro, de madeira, ou de barro, a multa (será) cinco vezes o seu valor; da mesma forma no caso de (dano a) flores, raízes e frutos.` },
        { id: 'cm-8-290', number: 'Verso 290', text: `Eles declaram a respeito de uma carruagem, do seu condutor e do seu dono, (que existem) dez casos em que nenhuma punição (por dano causado) pode ser infligida; em outros casos uma multa é prescrita.` },
        { id: 'cm-8-291', number: 'Verso 291', text: `Quando a corda do focinho arrebenta, quando o jugo se quebra, quando a carruagem vira de lado ou para trás, quando o eixo ou uma roda quebra,` },
        { id: 'cm-8-292', number: 'Verso 292', text: `Quando as correias de couro, a corda ao redor do pescoço ou as rédeas se rompem, e quando (o condutor) gritou em voz alta: 'Abram caminho', Manu declarou (que em todos esses casos) nenhuma punição (será infligida).` },
        { id: 'cm-8-293', number: 'Verso 293', text: `Mas se a carroça sai (da estrada) por falta de habilidade do condutor, o dono será multado, se houver dano, em duzentos (*panas*).` },
        { id: 'cm-8-294', number: 'Verso 294', text: `Se o condutor for hábil (mas negligente), apenas ele será multado; se o condutor for inábil, os ocupantes da carruagem (também) serão multados cada um em cem (*panas*).` },
        { id: 'cm-8-295', number: 'Verso 295', text: `Mas se ele for parado no seu caminho por gado ou por (outra) carruagem, e ele causar a morte de qualquer ser vivo, uma multa será imposta sem dúvida.` },
        { id: 'cm-8-296', number: 'Verso 296', text: `Se um homem for morto, a sua culpa será de imediato a mesma que a (de um) ladrão; para animais de grande porte como vacas, elefantes, camelos ou cavalos, metade disso.` },
        { id: 'cm-8-297', number: 'Verso 297', text: `Por ferir gado de pequeno porte a multa (será) duzentos (*panas*); a multa por belos quadrúpedes selvagens e pássaros deverá somar cinquenta (*panas*).` },
        { id: 'cm-8-298', number: 'Verso 298', text: `Para burros, ovelhas e cabras a multa será de cinco *mashas*; mas a punição por matar um cão ou um porco será de um *masha*.` },
        { id: 'cm-8-299', number: 'Verso 299', text: `Uma esposa, um filho, um escravo, um pupilo e um irmão (mais novo) de sangue total, que tenham cometido faltas, podem ser espancados com uma corda ou um bambu rachado,` },
        { id: 'cm-8-300', number: 'Verso 300', text: `Mas (apenas) na parte de trás do corpo, nunca numa parte nobre; aquele que os golpear de outro modo incorrerá na mesma culpa que um ladrão.` },
        { id: 'cm-8-301', number: 'Verso 301', text: `Assim, toda a lei de agressão (e ferimento) foi declarada completamente; explicarei agora as regras para a decisão (em casos) de roubo.` },
        { id: 'cm-8-302', number: 'Verso 302', text: `Que o rei se esforce ao máximo para punir os ladrões; pois, se ele pune os ladrões, a sua fama cresce e o seu reino prospera.` },
        { id: 'cm-8-303', number: 'Verso 303', text: `Aquele rei, de fato, é sempre digno de honra que garante a segurança (dos seus súditos); pois a sessão sacrificial (*sattra*, que ele, por assim dizer, realiza por esse meio) cresce sempre em duração, a segurança (dos seus súditos representando) a taxa sacrificial.` },
        { id: 'cm-8-304', number: 'Verso 304', text: `Um rei que (devidamente) protege (os seus súditos) recebe de todos e de cada um a sexta parte do seu mérito espiritual; se ele não os protege, a sexta parte do seu demérito também (recairá sobre ele).` },
        { id: 'cm-8-305', number: 'Verso 305', text: `Qualquer (mérito que um homem ganhe por) ler o Veda, por sacrificar, por doações de caridade, (ou por) adorar (Gurus e deuses), o rei obtém uma sexta parte disso em consequência de proteger devidamente (o seu reino).` },
        { id: 'cm-8-306', number: 'Verso 306', text: `Um rei que protege os seres criados de acordo com a lei sagrada e atinge os dignos de punição corporal, oferece diariamente (por assim dizer) sacrifícios nos quais centenas de milhares (são dados como) taxas.` },
        { id: 'cm-8-307', number: 'Verso 307', text: `Um rei que não oferece proteção, (mas) recebe a sua parte em espécie, os seus impostos, pedágios e taxas, presentes diários e multas, (após a morte) logo afundará no inferno.` },
        { id: 'cm-8-308', number: 'Verso 308', text: `Eles declaram que um rei que não oferece proteção, (mas) recebe a sexta parte da produção, toma sobre si toda a impureza de todo o seu povo.` },
        { id: 'cm-8-309', number: 'Verso 309', text: `Saiba que um rei que não presta atenção às regras (da lei), que é um ateu, e rapace, que não protege (os seus súditos, mas) os devora, afundará baixo (após a morte).` },
        { id: 'cm-8-310', number: 'Verso 310', text: `Que ele restrinja cuidadosamente os ímpios por três métodos: por aprisionamento, colocando-os em grilhões, e por vários (tipos de) punições corporais.` },
        { id: 'cm-8-311', number: 'Verso 311', text: `Pois ao punir os ímpios e ao favorecer os virtuosos, os reis são constantemente santificados, assim como os homens duas vezes nascidos pelos sacrifícios.` },
        { id: 'cm-8-312', number: 'Verso 312', text: `Um rei que deseja o seu próprio bem-estar deve sempre perdoar litigantes, crianças, idosos e doentes, que o insultem.` },
        { id: 'cm-8-313', number: 'Verso 313', text: `Aquele que, sendo abusado por homens em dor, (os) perdoa, será em recompensa desse (ato) exaltado no céu; mas aquele que, (orgulhoso) do seu estado real, não os perdoa, por essa (razão) afundará no inferno.` },
        { id: 'cm-8-314', number: 'Verso 314', text: `Um ladrão deverá, correndo, aproximar-se do rei, com cabelos soltos, confessando aquele roubo (e dizendo): 'Assim eu fiz, puna-me;'` },
        { id: 'cm-8-315', number: 'Verso 315', text: `(E ele deve) carregar no seu ombro um pilão, ou um porrete de madeira *Khadira*, ou uma lança afiada em ambas as pontas, ou um cajado de ferro.` },
        { id: 'cm-8-316', number: 'Verso 316', text: `Quer seja punido ou perdoado, o ladrão liberta-se da (culpa do) roubo; mas o rei, se não punir, toma sobre si a culpa do ladrão.` },
        { id: 'cm-8-317', number: 'Verso 317', text: `O assassino de um *Brahmana* erudito lança a sua culpa sobre aquele que come a sua comida, uma esposa adúltera sobre o seu marido (negligente), um pupilo ou sacrificador (pecador) sobre o (seu) professor (ou sacerdote negligente), um ladrão sobre o rei (que o perdoa).` },
        { id: 'cm-8-318', number: 'Verso 318', text: `Mas os homens que cometeram crimes e foram punidos pelo rei, vão para o céu, sendo puros como aqueles que realizaram ações meritórias.` },
        { id: 'cm-8-319', number: 'Verso 319', text: `Aquele que rouba a corda ou o pote de água de um poço, ou danifica uma cabana onde se distribui água, deverá pagar um *masha* como multa e restaurar o (artigo subtraído ou danificado) no seu (devido lugar).` },
        { id: 'cm-8-320', number: 'Verso 320', text: `Sobre aquele que rouba mais de dez *kumbhas* de grãos a punição corporal (será infligida); em outros casos ele será multado onze vezes mais, e deverá pagar ao (dono o valor de sua) propriedade.` },
        { id: 'cm-8-321', number: 'Verso 321', text: `Assim a punição corporal será infligida por roubar mais de cem (*palas*) de artigos vendidos por peso, (isto é) de ouro, prata, e assim por diante, e de roupas de excelência.` },
        { id: 'cm-8-322', number: 'Verso 322', text: `Por (roubar) mais de cinquenta (*palas*) é decretado que as mãos (do infrator) serão cortadas; mas em outros casos, que ele inflija uma multa de onze vezes o valor.` },
        { id: 'cm-8-323', number: 'Verso 323', text: `Por roubar homens de família nobre e especialmente mulheres e as joias mais preciosas, (o infrator) merece punição corporal (ou capital).` },
        { id: 'cm-8-324', number: 'Verso 324', text: `Por roubar animais de grande porte, armas ou remédios, que o rei fixe uma punição, após considerar o tempo e o propósito (para os quais foram destinados).` },
        { id: 'cm-8-325', number: 'Verso 325', text: `Por (roubar) vacas pertencentes a *Brahmanas*, perfurar (as narinas de) uma vaca estéril, e por roubar (outro) gado (pertencente a *Brahmanas*, o infrator) deverá perder imediatamente metade dos seus pés.` },
        { id: 'cm-8-326', number: 'Verso 326', text: `(Por roubar) fio, algodão, drogas que causam fermentação, esterco de vaca, melaço, leite azedo, leite doce, leitelho, água ou grama,` },
        { id: 'cm-8-327', number: 'Verso 327', text: `Vasos feitos de bambu ou outra cana, sal de vários tipos, (vasos) de barro, terra e cinzas,` },
        { id: 'cm-8-328', number: 'Verso 328', text: `Peixes, pássaros, óleo, manteiga clarificada, carne, mel e outras coisas que vêm de animais,` },
        { id: 'cm-8-329', number: 'Verso 329', text: `Ou outras coisas de tipo semelhante, bebida alcoólica, arroz cozido e todo tipo de comida cozida, a multa (será) o dobro do valor (do artigo roubado).` },
        { id: 'cm-8-330', number: 'Verso 330', text: `Por flores, milho verde, arbustos, trepadeiras, árvores e outros (grãos) sem casca a multa (será) de cinco *krishnalas*.` },
        { id: 'cm-8-331', number: 'Verso 331', text: `Por grãos descascados, vegetais, raízes e frutas a multa (será) de cem (*panas*) se não houver conexão (entre o dono e o ladrão), cinquenta (*panas*) se tal conexão existir.` },
        { id: 'cm-8-332', number: 'Verso 332', text: `Uma ofensa (desta descrição), que é cometida na presença (do proprietário) e com violência, será roubo; se (é cometida) na sua ausência, será furto; da mesma forma se (a posse de) qualquer coisa for negada após ter sido tomada.` },
        { id: 'cm-8-333', number: 'Verso 333', text: `Sobre aquele homem que possa roubar (qualquer um dos) artigos acima mencionados, quando eles estão preparados para (uso), que o rei inflija a primeira (ou menor) multa; da mesma forma sobre aquele que possa roubar um fogo (sagrado) do quarto (no qual é mantido).` },
        { id: 'cm-8-334', number: 'Verso 334', text: `Com qualquer membro que um ladrão de alguma forma cometa (uma ofensa) contra os homens, até mesmo desse (o rei) o privará a fim de evitar (uma repetição do crime).` },
        { id: 'cm-8-335', number: 'Verso 335', text: `Nem um pai, nem um professor, nem um amigo, nem uma mãe, nem uma esposa, nem um filho, nem um sacerdote doméstico devem ser deixados impunes por um rei, se não se mantiverem dentro do seu dever.` },
        { id: 'cm-8-336', number: 'Verso 336', text: `Onde outro homem comum seria multado em um *karshapana*, o rei será multado em mil; essa é a regra estabelecida.` },
        { id: 'cm-8-337', number: 'Verso 337', text: `Em (um caso de) roubo a culpa de um *Sudra* será óctupla, a de um *Vaisya* dezesseis vezes maior, a de um *Kshatriya* trinta e duas vezes maior,` },
        { id: 'cm-8-338', number: 'Verso 338', text: `A de um *Brahmana* sessenta e quatro vezes maior, ou exatamente cem vezes maior, ou (mesmo) duas vezes sessenta e quatro vezes maior; (cada um deles) conhecendo a natureza da ofensa.` },
        { id: 'cm-8-339', number: 'Verso 339', text: `(A tomada de) raízes e de frutas de árvores, de madeira para um fogo (sacrificial), e de grama para alimentar vacas, Manu declarou (ser) sem roubo.` },
        { id: 'cm-8-340', number: 'Verso 340', text: `Um *Brahmana*, buscando obter propriedade de um homem que tomou o que não lhe foi dado, seja sacrificando por ele ou ensinando-o, é como um ladrão.` },
        { id: 'cm-8-341', number: 'Verso 341', text: `Um homem duas vezes nascido, que está viajando e cujas provisões se esgotaram, não será multado, se ele pegar dois caules de cana-de-açúcar ou duas raízes (comestíveis) do campo de outro homem.` },
        { id: 'cm-8-342', number: 'Verso 342', text: `Aquele que amarra (gado de outros homens) desamarrado ou solta os amarrados, aquele que toma um escravo, um cavalo, ou uma carruagem terá incorrido na culpa de um ladrão.` },
        { id: 'cm-8-343', number: 'Verso 343', text: `Um rei que pune os ladrões de acordo com estas regras, ganhará fama neste mundo e após a morte bem-aventurança insuperável.` },
        { id: 'cm-8-344', number: 'Verso 344', text: `Um rei que deseja ganhar o trono de Indra e fama eterna imperecível, não deverá, nem por um momento, negligenciar (punir) o homem que comete violência.` },
        { id: 'cm-8-345', number: 'Verso 345', text: `Aquele que comete violência deve ser considerado o pior infrator, (mais iníquo) que um difamador, que um ladrão, e que aquele que fere (outro) com um cajado.` },
        { id: 'cm-8-346', number: 'Verso 346', text: `Mas aquele rei que perdoa o perpetrador de violência rapidamente perece e incorre em ódio.` },
        { id: 'cm-8-347', number: 'Verso 347', text: `Nem por amizade, nem por causa de grande lucro, deve um rei deixar ir perpetradores de violência, que causam terror a todas as criaturas.` },
        { id: 'cm-8-348', number: 'Verso 348', text: `Homens duas vezes nascidos podem pegar em armas quando (são) impedidos (no cumprimento de seus deveres, quando a destruição (ameaça) as castas duas vezes nascidas (*varna*) em tempos (maus),` },
        { id: 'cm-8-349', number: 'Verso 349', text: `Em sua própria defesa, numa contenda pelos honorários de sacerdotes oficiantes, e a fim de proteger mulheres e *Brahmanas*; aquele que (sob tais circunstâncias) mata pela causa do que é certo, não comete pecado.` },
        { id: 'cm-8-350', number: 'Verso 350', text: `Pode-se matar sem hesitação um assassino que se aproxima (com intenção assassina), seja (ele) professor, uma criança ou um homem idoso, ou um *Brahmana* profundamente versado nos Vedas.` },
        { id: 'cm-8-351', number: 'Verso 351', text: `Ao matar um assassino o matador não incorre em culpa, quer (o faça) pública ou secretamente; nesse caso a fúria recai sobre a fúria.` },
        { id: 'cm-8-352', number: 'Verso 352', text: `Os homens que cometem adultério com as esposas de outros, o rei mandará que sejam marcados por punições que causem terror, e depois banidos.` },
        { id: 'cm-8-353', number: 'Verso 353', text: `Pois pelo (adultério) é causada uma mistura das castas (*varna*) entre os homens; daí (segue-se) o pecado, que corta até mesmo as raízes e causa a destruição de tudo.` },
        { id: 'cm-8-354', number: 'Verso 354', text: `Um homem anteriormente acusado de (tais) ofensas, que conversa secretamente com a esposa de outro homem, pagará a primeira (ou menor) multa.` },
        { id: 'cm-8-355', number: 'Verso 355', text: `Mas um homem, não acusado antes, que (assim) fala com (uma mulher) por alguma causa (razoável), não incorrerá em nenhuma culpa, uma vez que nele não há transgressão.` },
        { id: 'cm-8-356', number: 'Verso 356', text: `Aquele que aborda a esposa de outro homem num *Tirtha*, fora da aldeia, numa floresta, ou na confluência de rios, sofrerá (a punição por) atos adúlteros (*samgrahana*).` },
        { id: 'cm-8-357', number: 'Verso 357', text: `Oferecer presentes (a uma mulher), brincar (com ela), tocar os seus ornamentos e vestido, sentar com ela numa cama, todos (esses atos) são considerados atos adúlteros (*samgrahana*).` },
        { id: 'cm-8-358', number: 'Verso 358', text: `Se alguém toca uma mulher num lugar (que) não (deveria ser tocado) ou permite (ser tocado em tal lugar), todos (tais atos feitos) com consentimento mútuo são declarados (ser) adúlteros (*samgrahana*).` },
        { id: 'cm-8-359', number: 'Verso 359', text: `Um homem que não é um *Brahmana* deve sofrer a morte por adultério (*samgrahana*); pois as esposas de todas as quatro castas devem sempre ser cuidadosamente guardadas.` },
        { id: 'cm-8-360', number: 'Verso 360', text: `Mendigos, bardos, homens que realizaram a cerimônia iniciatória de um sacrifício Védico, e artesãos não estão proibidos de falar com mulheres casadas.` },
        { id: 'cm-8-361', number: 'Verso 361', text: `Que nenhum homem converse com as esposas de outros depois de ter sido proibido (de fazê-lo); mas aquele que conversa (com elas), apesar de uma proibição, será multado em um *suvarna*.` },
        { id: 'cm-8-362', number: 'Verso 362', text: `Esta regra não se aplica às esposas de atores e cantores, nem (daqueles) que vivem das (intrigas de) suas próprias (esposas); pois tais homens enviam as suas esposas (para outros) ou, escondendo-se, permitem que elas mantenham relações criminosas.` },
        { id: 'cm-8-363', number: 'Verso 363', text: `No entanto, aquele que conversa secretamente com tais mulheres, ou com escravas mantidas por um (senhor), e com ascetas femininas, será compelido a pagar uma pequena multa.` },
        { id: 'cm-8-364', number: 'Verso 364', text: `Aquele que viola uma donzela involuntária sofrerá instantaneamente punição corporal; mas um homem que desfruta de uma donzela disposta não sofrerá punição corporal, se (sua casta for) a mesma (que a dela).` },
        { id: 'cm-8-365', number: 'Verso 365', text: `De uma donzela que faz avanços a um (homem de) alta (casta), ele não cobrará nenhuma multa; mas a ela, que corteja um (homem de) baixa (casta), que ele force a viver confinada em sua casa.` },
        { id: 'cm-8-366', number: 'Verso 366', text: `Um (homem de) baixa (casta) que faz amor com uma donzela (da) mais alta (casta) sofrerá punição corporal; aquele que aborda uma donzela (de) casta igual pagará a taxa nupcial, se o pai dela assim o desejar.` },
        { id: 'cm-8-367', number: 'Verso 367', text: `Mas se qualquer homem por insolência contaminar à força uma donzela, dois dos seus dedos serão instantaneamente cortados, e ele pagará uma multa de seiscentos (*panas*).` },
        { id: 'cm-8-368', number: 'Verso 368', text: `Um homem (de) casta igual que corrompe uma donzela disposta não sofrerá a amputação de seus dedos, mas pagará uma multa de duzentos (*panas*) a fim de dissuadi-lo de uma repetição (da ofensa).` },
        { id: 'cm-8-369', number: 'Verso 369', text: `Uma donzela que corrompe (outra) donzela deve ser multada em duzentos (*panas*), pagar o dobro da sua taxa (nupcial) e receber dez (chibatadas com uma) vara.` },
        { id: 'cm-8-370', number: 'Verso 370', text: `Mas uma mulher que corrompe uma donzela terá instantaneamente (a sua cabeça) raspada ou dois dedos cortados, e será forçada a cavalgar (através da cidade) num burro.` },
        { id: 'cm-8-371', number: 'Verso 371', text: `Se uma esposa, orgulhosa da grandeza dos seus parentes ou de (sua própria) excelência, viola o dever que deve ao seu senhor, o rei mandará que ela seja devorada por cães num lugar frequentado por muitos.` },
        { id: 'cm-8-372', number: 'Verso 372', text: `Que ele mande queimar o infrator masculino numa cama de ferro em brasa; colocarão toras sob ela, (até que) o pecador seja queimado (até à morte).` },
        { id: 'cm-8-373', number: 'Verso 373', text: `Sobre um homem (uma vez) condenado, que é (novamente) acusado dentro de um ano, uma multa dupla (deve ser infligida); mesmo assim (deve a multa ser dobrada) por relação sexual (repetida) com uma *Vratya* e uma *Kandali*.` },
        { id: 'cm-8-374', number: 'Verso 374', text: `Um *Sudra* que tem relações sexuais com uma mulher de uma casta duas vezes nascida (*varna*), guardada ou não guardada, (será punido da seguinte maneira): se ela não era guardada, ele perde a parte (ofensora) e toda a sua propriedade; se ela era guardada, tudo (mesmo a sua vida).` },
        { id: 'cm-8-375', number: 'Verso 375', text: `(Por relação sexual com uma *Brahmana* guardada, um *Vaisya* perderá toda a sua propriedade após prisão por um ano; um *Kshatriya* será multado em mil (*panas*) e será raspado com a urina (de um asno).` },
        { id: 'cm-8-376', number: 'Verso 376', text: `Se um *Vaisya* ou um *Kshatriya* tem conexão com uma *Brahmana* não guardada, que multe o *Vaisya* em quinhentos (*panas*) e o *Kshatriya* em mil.` },
        { id: 'cm-8-377', number: 'Verso 377', text: `Mas mesmo estes dois, se ofenderem com uma *Brahmani* (não apenas) guardada (mas esposa de um homem eminente), serão punidos como um *Sudra* ou queimados num fogo de grama seca.` },
        { id: 'cm-8-378', number: 'Verso 378', text: `Um *Brahmana* que conhece carnalmente uma *Brahmani* guardada contra a vontade dela, será multado em mil (*panas*); mas ele será obrigado a pagar quinhentos, se teve conexão com uma disposta.` },
        { id: 'cm-8-379', number: 'Verso 379', text: `A tonsura (da cabeça) é ordenada para um *Brahmana* (em vez da) punição capital; mas (homens de) outras castas sofrerão punição capital.` },
        { id: 'cm-8-380', number: 'Verso 380', text: `Que ele nunca mate um *Brahmana*, embora este tenha cometido todos os crimes (possíveis); que ele bana tal (infrator), deixando toda a sua propriedade (com ele) e (o seu corpo) ileso.` },
        { id: 'cm-8-381', number: 'Verso 381', text: `Nenhum crime maior é conhecido na terra do que matar um *Brahmana*; um rei, portanto, não deve sequer conceber em sua mente o pensamento de matar um *Brahmana*.` },
        { id: 'cm-8-382', number: 'Verso 382', text: `Se um *Vaisya* se aproxima de uma mulher guardada da casta *Kshatriya*, ou um *Kshatriya* de uma mulher *Vaisya* (guardada), ambos merecem a mesma punição que no caso de uma mulher *Brahmana* não guardada.` },
        { id: 'cm-8-383', number: 'Verso 383', text: `Um *Brahmana* será compelido a pagar uma multa de mil (*panas*) se tiver relação com (mulheres) guardadas daquelas duas (castas); por (ofender com) uma mulher *Sudra* (guardada) uma multa de mil (*panas* será infligida) a um *Kshatriya* ou a um *Vaisya*.` },
        { id: 'cm-8-384', number: 'Verso 384', text: `Por (relação com) uma *Kshatriya* não guardada, uma multa de quinhentos (*panas* recairá) sobre um *Vaisya*; mas (pela mesma ofensa) um *Kshatriya* será raspado com a urina (de um burro) ou (pagará) a mesma multa.` },
        { id: 'cm-8-385', number: 'Verso 385', text: `Um *Brahmana* que se aproxima de mulheres não guardadas (das castas) *Kshatriya* ou *Vaisya*, ou uma mulher *Sudra*, será multado em quinhentos (*panas*); mas (por relação com) uma mulher (das castas) mais baixas, mil.` },
        { id: 'cm-8-386', number: 'Verso 386', text: `Aquele rei em cuja cidade não vive nenhum ladrão, nenhum adúltero, nenhum difamador, nenhum homem culpado de violência, e nenhum perpetrador de agressões, alcança o mundo de *Sakra* (Indra).` },
        { id: 'cm-8-387', number: 'Verso 387', text: `A supressão desses cinco nos seus domínios assegura a um rei a soberania suprema entre os seus pares e fama no mundo.` },
        { id: 'cm-8-388', number: 'Verso 388', text: `Um sacrificador que abandona um sacerdote oficiante, e um sacerdote oficiante que abandona um sacrificador, (estando cada um) apto para realizar a sua obra e não contaminado (por crimes graves), devem cada um ser multados em cem (*panas*).` },
        { id: 'cm-8-389', number: 'Verso 389', text: `Nem uma mãe, nem um pai, nem uma esposa, nem um filho deverão ser rejeitados; aquele que os rejeita, a menos que seja culpado de um crime que cause a perda de casta, será multado em seiscentos (*panas*).` },
        { id: 'cm-8-390', number: 'Verso 390', text: `Se homens duas vezes nascidos disputam entre si a respeito do dever das ordens, um rei que deseja o seu próprio bem-estar não deve decidir (apressadamente) (qual é) a lei.` },
        { id: 'cm-8-391', number: 'Verso 391', text: `Tendo-lhes mostrado a devida honra, ele deve, com (a assistência de) *Brahmanas*, primeiro acalmá-los com (fala) gentil e depois ensinar-lhes o seu dever.` },
        { id: 'cm-8-392', number: 'Verso 392', text: `Um *Brahmana* que não convida o seu vizinho próximo e o seu vizinho seguinte a esse, (embora) ambos (sejam) dignos (da honra), a um festival no qual vinte *Brahmanas* são entretidos, está sujeito a uma multa de um *masha*.` },
        { id: 'cm-8-393', number: 'Verso 393', text: `Um *Srotriya* que não entretém um *Srotriya* virtuoso em ritos festivos auspiciosos, será obrigado a pagar-lhe o dobro (do valor da) refeição e um *masha* de ouro (como multa ao rei).` },
        { id: 'cm-8-394', number: 'Verso 394', text: `Um cego, um idiota, (um aleijado) que se move com a ajuda de uma tábua, um homem com setenta anos completos, e aquele que confere benefícios aos *Srotriyas*, não serão compelidos por nenhum (rei) a pagar um imposto.` },
        { id: 'cm-8-395', number: 'Verso 395', text: `Que o rei trate sempre com bondade um *Srotriya*, um doente ou angustiado, um infante e um homem idoso ou indigente, um homem de alto nascimento e um homem honrado (*Arya*).` },
        { id: 'cm-8-396', number: 'Verso 396', text: `Um lavadeiro deverá lavar (as roupas dos seus patrões) suavemente sobre uma tábua lisa de madeira de *Salmali*; ele não deverá trocar as roupas (de uma pessoa) pelas (de outra), nem permitir que ninguém (exceto o dono) as vista.` },
        { id: 'cm-8-397', number: 'Verso 397', text: `Um tecelão (que recebeu) dez *palas* (de fio), deverá devolver (pano pesando) um *pala* a mais; aquele que agir de modo diferente será compelido a pagar uma multa de doze (*panas*).` },
        { id: 'cm-8-398', number: 'Verso 398', text: `Que o rei tome um vigésimo daquele (valor) que homens, bem familiarizados com o acerto de pedágios e taxas (e) hábeis em (estimar o valor de) todos os tipos de mercadoria, possam fixar como o valor de cada mercadoria à venda.` },
        { id: 'cm-8-399', number: 'Verso 399', text: `Que o rei confisque a propriedade inteira de (um comerciante) que, por ganância, exporta mercadorias das quais o rei tem monopólio ou (cuja exportação é) proibida.` },
        { id: 'cm-8-400', number: 'Verso 400', text: `Aquele que evita a alfândega (ou um pedágio), aquele que compra ou vende num momento impróprio, ou aquele que faz uma declaração falsa ao enumerar (as suas mercadorias), será multado em oito vezes (o valor da taxa) que tentou evadir.` },
        { id: 'cm-8-401', number: 'Verso 401', text: `Que (o rei) fixe (as taxas para) a compra e venda de todos os bens comercializáveis, tendo considerado (devidamente) de onde vêm, para onde vão, por quanto tempo foram guardados, o lucro (provável) e o gasto (provável).` },
        { id: 'cm-8-402', number: 'Verso 402', text: `Uma vez a cada cinco noites, ou no fim de cada quinzena, que o rei estabeleça publicamente os preços para os (mercadores).` },
        { id: 'cm-8-403', number: 'Verso 403', text: `Todos os pesos e medidas devem ser devidamente marcados, e uma vez a cada seis meses que ele os reexamine.` },
        { id: 'cm-8-404', number: 'Verso 404', text: `Numa balsa (ou travessia) uma carroça (vazia) será obrigada a pagar um *pana*, a (carga) de um homem meio *pana*, um animal e uma mulher um quarto de (*pana*), um homem sem carga a metade de um quarto.` },
        { id: 'cm-8-405', number: 'Verso 405', text: `Carroças (carregadas) com vasos cheios (de mercadorias) serão obrigadas a pagar pedágio numa balsa de acordo com o valor (das mercadorias), vasos vazios e homens sem bagagem alguma ninharia.` },
        { id: 'cm-8-406', number: 'Verso 406', text: `Para uma longa travessia, o aluguel do barco deve ser proporcional aos lugares e tempos; saiba que esta (regra se refere) a (travessias ao longo) das margens de rios; no mar não há (frete) fixado.` },
        { id: 'cm-8-407', number: 'Verso 407', text: `Mas uma mulher grávida de dois meses ou mais, um asceta, um eremita na floresta, e *Brahmanas* que são estudantes do Veda, não serão obrigados a pagar pedágio numa travessia.` },
        { id: 'cm-8-408', number: 'Verso 408', text: `O que quer que seja danificado num barco por culpa dos barqueiros, deverá ser compensado coletivamente pelos barqueiros, (pagando cada um) a sua parte.` },
        { id: 'cm-8-409', number: 'Verso 409', text: `Esta decisão em processos (movidos) por passageiros (é válida apenas) no caso dos barqueiros serem culpavelmente negligentes na água; no caso de (um acidente) causado pela (vontade dos) deuses, nenhuma multa pode ser (infligida a eles).` },
        { id: 'cm-8-410', number: 'Verso 410', text: `(O rei) deve ordenar a um *Vaisya* que comercialize, que empreste dinheiro, que cultive a terra ou que cuide do gado, e a um *Sudra* que sirva as castas duas vezes nascidas.` },
        { id: 'cm-8-411', number: 'Verso 411', text: `(Algum) *Brahmana* (rico) deve compassivamente apoiar tanto um *Kshatriya* quanto um *Vaisya*, se estiverem em dificuldades de sustento, empregando-os num trabalho (adequado às) suas (castas).` },
        { id: 'cm-8-412', number: 'Verso 412', text: `Mas um *Brahmana* que, por ser poderoso, por ganância faça homens iniciados (das castas) duas vezes nascidas fazerem contra a sua vontade o trabalho de escravos, será multado pelo rei em seiscentos (*panas*).` },
        { id: 'cm-8-413', number: 'Verso 413', text: `Mas a um *Sudra*, quer comprado ou não, ele pode compelir a fazer trabalho servil; pois ele foi criado pelo Auto-existente (*Svayambhu*) para ser escravo de um *Brahmana*.` },
        { id: 'cm-8-414', number: 'Verso 414', text: `Um *Sudra*, embora emancipado pelo seu senhor, não é libertado da servidão; uma vez que isso lhe é inato, quem o pode libertar disso?` },
        { id: 'cm-8-415', number: 'Verso 415', text: `Existem escravos de sete tipos, (a saber) o que é feito cativo sob um estandarte, o que serve pela sua comida diária, o que nasce na casa, o que é comprado e o que é dado, o que é herdado de ancestrais e o que é escravizado como forma de punição.` },
        { id: 'cm-8-416', number: 'Verso 416', text: `Uma esposa, um filho e um escravo, declara-se que estes três não têm propriedade; a riqueza que eles ganham é (adquirida) para aquele a quem pertencem.` },
        { id: 'cm-8-417', number: 'Verso 417', text: `Um *Brahmana* pode confiantemente apoderar-se dos bens do (seu) escravo *Sudra*; pois, como aquele (escravo) não pode ter propriedade, o seu senhor pode tomar as suas posses.` },
        { id: 'cm-8-418', number: 'Verso 418', text: `(O rei) deve cuidadosamente compelir os *Vaisyas* e *Sudras* a realizarem o trabalho (prescrito) para eles; pois se estas duas (castas) se desviassem dos seus deveres, lançariam este mundo (inteiro) na confusão.` },
        { id: 'cm-8-419', number: 'Verso 419', text: `Que ele cuide diariamente da conclusão dos seus empreendimentos, das suas bestas de carga e carruagens, (da arrecadação das) suas receitas e dos desembolsos, das suas minas e do seu tesouro.` },
        { id: 'cm-8-420', number: 'Verso 420', text: `Um rei que assim leva a uma conclusão todos os negócios legais enumerados acima, e remove todo o pecado, alcança o estado mais elevado (de bem-aventurança).` },
      ],
    },
  ],
};
